engine.evalLogicCondition:
function evalLogicCondition(condStr, answers) {
  if (condStr === "true") return true;
  var op = condStr.indexOf("!=") !== -1 ? "!=" : "==";
  var parts = condStr.split(op);
  if (parts.length < 2) return false;
  var k = parts[0].trim();
  var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
  var actual = answers && answers[k];
  if (actual === undefined) return false;
  return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
}

// Extract unique [[...]] / {{...}} placeholders from text. Mirrors v2
// runTemplateScan regex pair (line 6440). Returns array of unique
// placeholder strings as they appear in the doc.

engine.extractTemplatePlaceholders:
function extractTemplatePlaceholders(text) {
  var src = String(text || "");
  var found = {};
  var bracketRe = /(\$!|\$|!)?\[\[(.*?)\]\]/g, bm;
  while ((bm = bracketRe.exec(src))) if (bm[0].length > 2) found[bm[0]] = true;
  var curlyRe = /\{\{([^}]+)\}\}(\*)?/g, cm;
  while ((cm = curlyRe.exec(src))) if (cm[0].length > 4) found[cm[0]] = true;
  return Object.keys(found);
}

engine.analyze:
async function analyze(input, providers) {
  function _esc(s) { return String(s == null ? "" : s); }

  // Load persisted state from Office settings (set by v2 persistAgreementState).
  function _readPersistedAgreement() {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return null;
      var name = s.get("AgreementDataName");
      var type = s.get("AgreementDataType");
      var details = s.get("AgreementDataDetails");
      if (!name && !type && !details) return null;
      return {
        name: name || null,
        type: type || null,
        details: typeof details === "object" ? details : null,
      };
    } catch (e) {
      if (window.eli && window.eli.log) {
        window.eli.log.event("tool", "build_draft_persist_read_failed", { msg: e && e.message });
      }
      return null;
    }
  }

  // First-instance scan for whole-word OARS anywhere in body
  // (case-insensitive). Matches kernel's _eliCheckOarsAndLaunch.
  function _hasOarsAnywhere(bodyText) {
    if (!bodyText) return false;
    return /\bOARS\b/i.test(String(bodyText));
  }

  // Best-effort agreement-type extraction from OARS-formatted body text.
  // OARS docs have "Agreement Type: <type>" lines near the top.
  function _extractAgreementType(bodyText) {
    if (!bodyText) return null;
    var m = String(bodyText).match(/Agreement\s+Type\s*[:=]\s*([^\n\r]+)/i);
    return m ? m[1].trim() : null;
  }

  // Extract key/value pairs. Anchors on first OARS line if present,
  // otherwise parses the whole text. "Field: value" or "Field = value".
  function _extractFields(bodyText) {
    if (!bodyText) return {};
    var lines = String(bodyText).split(/\r?\n/);
    var startIdx = 0;
    for (var j = 0; j < lines.length; j++) {
      if (/\bOARS\b/i.test(lines[j])) { startIdx = j; break; }
    }
    var fields = {};
    var stop = false;
    for (var i = startIdx; i < lines.length && !stop; i++) {
      var ln = lines[i].trim();
      if (!ln) {
        if (Object.keys(fields).length) stop = true;
        continue;
      }
      var m = ln.match(/^([A-Za-z][A-Za-z0-9 _\-]+?)\s*[:=]\s*(.+)$/);
      if (m) fields[m[1].trim()] = m[2].trim();
    }
    return fields;
  }

  // Three OARS data sources (priority order):
  //   1. footerFile — manually uploaded via kernel's DATA loader
  //   2. doc body — auto-scanned
  //   3. doc headers — fallback
  // Highest-priority source with OARS marker wins. Sources are
  // concatenated for fallback field extraction.
  var bodyText   = (input && input.bodyText) || "";
  var headerText = (input && input.headerText) || "";
  var footerText = (input && input.footerFile && input.footerFile.text) || "";
  var footerName = (input && input.footerFile && input.footerFile.name) || null;

  var sourceText = "";
  var source = "none";
  if (_hasOarsAnywhere(footerText))      { sourceText = footerText; source = "footer_file"; }
  else if (_hasOarsAnywhere(bodyText))   { sourceText = bodyText;   source = "doc_body"; }
  else if (_hasOarsAnywhere(headerText)) { sourceText = headerText; source = "doc_header"; }
  else if (footerText)                   { sourceText = footerText; source = "footer_file_no_marker"; }

  var hasOars = source !== "none" && source !== "footer_file_no_marker";
  var persisted = _readPersistedAgreement();
  var detectedType = (persisted && persisted.type) || _extractAgreementType(sourceText);
  var fields = sourceText ? _extractFields(sourceText) : {};

  var releasedAt = "unknown";
  try {
    if (typeof window !== "undefined" && window.eli && window.eli.tools && window.eli.tools._loaded
        && window.eli.tools._loaded["build_draft"]) {
      releasedAt = window.eli.tools._loaded["build_draft"].releasedAt || "unknown";
    }
  } catch (e) {
    if (window.eli && window.eli.log) {
      window.eli.log.event("tool", "build_draft_releasedat_lookup_failed", { msg: e && e.message });
    }
  }

  // FROM v2 runDocumentScannerBuild (line 21358) — count {{...}} markers.
  // Read-only; the actual logic builder runs as wizard step 1.
  function _scanLogicMarkers(text) {
    var counts = { IF: 0, ELSEIF: 0, ELSE: 0, ENDIF: 0, DEF: 0, TITLE: 0, DELETE_LINE: 0, ENTER: 0, otherCurly: 0 };
    var defKeys = [];
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(String(text || "")))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) counts.IF++;
      else if (t.indexOf("ELSEIF:") === 0) counts.ELSEIF++;
      else if (t.indexOf("ELSE") === 0) counts.ELSE++;
      else if (t.indexOf("ENDIF") === 0) counts.ENDIF++;
      else if (t.indexOf("DEF:") === 0) {
        counts.DEF++;
        var kv = t.substring(4).split("|")[0].split("=")[0].trim();
        if (kv) defKeys.push(kv);
      }
      else if (t.indexOf("TITLE:") === 0) counts.TITLE++;
      else if (t === "DELETE_LINE") counts.DELETE_LINE++;
      else if (t === "ENTER") counts.ENTER++;
      else counts.otherCurly++;
    }
    var total = 0;
    for (var k in counts) total += counts[k];
    return { counts: counts, total: total, defKeys: defKeys };
  }

  // [Placeholder text] — square brackets used as fill targets (FROM v2
  // showBracketCleaner line 22706). Skips obvious false-positives like
  // citation refs ([1], [Author]).
  function _scanBrackets(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\[([^\[\]\n]{2,80})\]/g, m;
    while ((m = re.exec(src))) {
      var inner = m[1].trim();
      // Skip pure-numeric refs ([1], [42]), single-word author cites,
      // and Word's tracked-change markers.
      if (/^\d+$/.test(inner)) continue;
      if (/^\[Comment[ \d]/i.test(m[0])) continue;
      matches.push({ text: m[0], inner: inner, index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // $ amounts in body — financial review trigger.
  function _scanFinancial(text) {
    var src = String(text || "");
    var matches = [];
    var re = /\$\s*[\d,]+(?:\.\d+)?/g, m;
    while ((m = re.exec(src))) {
      matches.push({ text: m[0].replace(/\s+/g, ""), index: m.index });
    }
    return { items: matches.slice(0, 50), total: matches.length };
  }

  // Full DEF parser — mirrors v2 parseLogicDefinition (line 21405).
  // Walks {{IF/ELSEIF/ELSE/ENDIF}} stack and records {{DEF:k=default|opts|warning}}
  // entries with their parent IF expressions as visibility dependencies.
  function _parseLogicDefs(text) {
    var src = String(text || "");
    var defs = {};
    var deps = {};
    var stack = [];
    var title = null;
    var titleMatch = src.match(/\{\{TITLE:\s*([^{}]+)\}\}/i);
    if (titleMatch) title = titleMatch[1].trim();
    var re = /\{\{([^{}]+)\}\}/g, m;
    while ((m = re.exec(src))) {
      var t = m[1].trim();
      if (t.indexOf("IF:") === 0) stack.push(t.substring(3).trim());
      else if (t.indexOf("ELSEIF:") === 0) {
        if (stack.length) { stack.pop(); stack.push(t.substring(7).trim()); }
      }
      else if (t.indexOf("ELSE") === 0) {
        if (stack.length) { stack.pop(); stack.push("true"); }
      }
      else if (t.indexOf("ENDIF") === 0) {
        if (stack.length) stack.pop();
      }
      else if (t.indexOf("DEF:") === 0 && t.indexOf("|") !== -1) {
        var clean = t.substring(4).trim();
        var pipe = clean.split("|");
        var defPart = pipe[0].trim();
        var optionsPart = pipe.length > 1 ? pipe[1].trim() : null;
        var warning = pipe.length > 2 ? pipe[2].trim() : null;
        if (!optionsPart) continue;
        var defSplit = defPart.split("=");
        var key = defSplit[0].trim();
        var explicitDefault = defSplit.length > 1 ? defSplit[1].trim() : "";
        var isText = optionsPart.charAt(0) === "*";
        var textDefault = isText ? optionsPart.substring(1).trim() : "";
        defs[key] = {
          default: explicitDefault || textDefault,
          isText: isText,
          options: isText ? [] : optionsPart.split(",").map(function (o) { return o.trim(); }),
          warning: warning,
        };
        if (stack.length > 0) deps[key] = stack.slice();
      }
    }
    return { defs: defs, deps: deps, count: Object.keys(defs).length, title: title };
  }

  var logicScan = _scanLogicMarkers(bodyText);
  var bracketScan = _scanBrackets(bodyText);
  var financialScan = _scanFinancial(bodyText);
  var logicDefs = _parseLogicDefs(bodyText);

  var sourceLabel = source === "footer_file" ? ("File: " + (footerName || "uploaded"))
                  : source === "footer_file_no_marker" ? ("File: " + (footerName || "uploaded"))
                  : source === "doc_body"   ? "Document body"
                  : source === "doc_header" ? "Document header"
                  : null;
  return {
    items: [],
    overview: hasOars
      ? ("OARS · " + (sourceLabel || "detected") + (detectedType ? " · " + detectedType : ""))
      : (footerText ? ("File loaded · " + (footerName || "—"))
        : persisted ? ("Saved · " + (persisted.type || persisted.name || "—")) : "Standard mode"),
    hasOars: hasOars,
    source: source,
    sourceLabel: sourceLabel,
    footerFile: input && input.footerFile ? { name: footerName, size: input.footerFile.size } : null,
    persisted: persisted,
    detectedType: detectedType,
    fieldCount: Object.keys(fields).length,
    fields: fields,
    logicScan: logicScan,
    bracketScan: bracketScan,
    financialScan: financialScan,
    logicDefs: logicDefs,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: releasedAt,
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

view.renderHub:
function renderHub(opts) {
  var result = opts.result || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var onClose = opts.onClose || function () {};
  var onRunAll = opts.onRunAll || function () {};
  var onTemplates = opts.onTemplates || function () {};
  var onStep = opts.onStep || function () {};
  var onClearOars = opts.onClearOars || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root";

  // Header bar
  var bar = document.createElement("div");
  bar.className = "_eli3_bd_bar";
  bar.innerHTML =
    '<button class="_eli3_bd_back" title="Back">←</button>' +
    '<div class="_eli3_bd_title">⚡ Build Draft Hub</div>' +
    '<div class="_eli3_bd_overview">' + _esc(result.overview || "") + '</div>';
  bar.querySelector("._eli3_bd_back").onclick = onClose;
  root.appendChild(bar);

  // OARS status banner — shown when ANY source has data: OARS-marked
  // body/header, persisted state, or a footer-uploaded file.
  if (result.hasOars || result.persisted || result.footerFile) {
    var banner = document.createElement("div");
    banner.className = "_eli3_bd_oars_banner";
    var typeLabel = (result.detectedType || (result.persisted && result.persisted.type) || "—");
    var nameLabel = (result.persisted && result.persisted.name)
                  || (result.footerFile && result.footerFile.name)
                  || (result.hasOars ? "OARS document" : "");
    var sourceLine = result.sourceLabel
      ? '<div class="_eli3_bd_oars_source">' + _esc(result.sourceLabel) + '</div>'
      : '';
    banner.innerHTML =
      '<div class="_eli3_bd_oars_icon">📋</div>' +
      '<div class="_eli3_bd_oars_main">' +
        '<div class="_eli3_bd_oars_label">OARS DATA</div>' +
        '<div class="_eli3_bd_oars_value">' + _esc(typeLabel) + (nameLabel ? ' · ' + _esc(nameLabel) : '') + '</div>' +
        sourceLine +
        (result.fieldCount ? '<div class="_eli3_bd_oars_meta">' + result.fieldCount + ' field' + (result.fieldCount === 1 ? "" : "s") + ' parsed</div>' : '') +
      '</div>' +
      '<button class="_eli3_bd_oars_clear" title="Clear OARS data">✕</button>';
    banner.querySelector("._eli3_bd_oars_clear").onclick = onClearOars;
    root.appendChild(banner);
  }

  // Primary actions
  var actions = document.createElement("div");
  actions.className = "_eli3_bd_actions";
  var runAll = document.createElement("button");
  runAll.className = "_eli3_bd_run_all";
  runAll.innerHTML = '<span class="_eli3_bd_run_all_icon">🚀</span> RUN ALL 4 STEPS';
  runAll.onclick = onRunAll;
  actions.appendChild(runAll);
  var templates = document.createElement("button");
  templates.className = "_eli3_bd_templates";
  templates.innerHTML = '<span class="_eli3_bd_templates_icon">📂</span> TEMPLATES';
  templates.onclick = onTemplates;
  actions.appendChild(templates);
  root.appendChild(actions);

  // Per-step list. Mirrors v2 renderAutoFillHubUI (line 21254): 4 steps,
  // Logic → Fill → Error Review → Save. Counts pulled from engine scans
  // for at-a-glance signal.
  var lc = (result.logicScan && result.logicScan.counts) || {};
  var logicTotal = (result.logicScan && result.logicScan.total) || 0;
  var bracketTotal = (result.bracketScan && result.bracketScan.total) || 0;
  var financialTotal = (result.financialScan && result.financialScan.total) || 0;
  var fillCount = bracketTotal + financialTotal;
  var steps = [
    { n: 1, icon: "🏗️", label: "Build Logic", desc: logicTotal
        ? (logicTotal + " marker" + (logicTotal === 1 ? "" : "s") + " (" +
           (lc.IF || 0) + " IF · " + (lc.DEF || 0) + " DEF · " + (lc.TITLE || 0) + " TITLE)")
        : "Generate custom draft from {{IF}} logic.", id: "logic", count: logicTotal },
    { n: 2, icon: "✍️", label: "Fill Fields", desc: fillCount
        ? (bracketTotal + " bracket" + (bracketTotal === 1 ? "" : "s") +
           (financialTotal ? " · " + financialTotal + " $ amount" + (financialTotal === 1 ? "" : "s") : ""))
        : "Populate [Bracketed] placeholders.", id: "templates", count: fillCount },
    { n: 3, icon: "📝", label: "Error Review", desc: "Full grammar & proofreading scan.", id: "error_review", count: 0 },
    { n: 4, icon: "💾", label: "Save and/or Send", desc: "Finalize document and draft email.", id: "save", count: 0 },
  ];
  var list = document.createElement("div");
  list.className = "_eli3_bd_steps";
  steps.forEach(function (s) {
    var row = document.createElement("button");
    row.className = "_eli3_bd_step";
    var badge = s.count ? '<span class="_eli3_bd_step_badge">' + s.count + '</span>' : '';
    row.innerHTML =
      '<span class="_eli3_bd_step_n">' + s.n + '</span>' +
      '<span class="_eli3_bd_step_icon">' + s.icon + '</span>' +
      '<span class="_eli3_bd_step_info">' +
        '<span class="_eli3_bd_step_label">' + _esc(s.label) + badge + '</span>' +
        '<span class="_eli3_bd_step_desc">' + _esc(s.desc) + '</span>' +
      '</span>' +
      '<span class="_eli3_bd_step_arrow">→</span>';
    row.onclick = function () { onStep(s.id, s); };
    list.appendChild(row);
  });
  root.appendChild(list);

  // Footer note (migration in progress)
  var foot = document.createElement("div");
  foot.className = "_eli3_bd_foot";
  foot.innerHTML = "Wizard steps run in v2 mode until each is migrated. " +
    "OARS detection + Hub UI are v3-native.";
  root.appendChild(foot);

  mount.appendChild(root);
}

// renderLogicForm — Step 1 v3-native port of v2 renderLogicBuilderForm
// (line 21428). Reads engine result.logicDefs (defs + deps) and renders
// a fill-in form with visibility tracking. onGenerate(answers) runs the
// Word.run replacement pipeline in init.js.

view.renderLogicForm:
function renderLogicForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var defs = opts.defs || {};
  var deps = opts.deps || {};
  var docTitle = opts.title || "Document Builder";
  var onGenerate = opts.onGenerate || function () {};
  var onBack = opts.onBack || function () {};
  var onScanForOars = opts.onScanForOars || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_logic";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">🏗️ ' + _esc(docTitle) + '</div>' +
      '<div class="_eli3_bd_overview">LOGIC ENGINE</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;

  var keys = Object.keys(defs);
  if (!keys.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_logic_empty";
    empty.innerHTML =
      '<div class="_eli3_bd_logic_empty_icon">📄</div>' +
      '<div class="_eli3_bd_logic_empty_title">NO LOGIC TAGS FOUND</div>' +
      '<div class="_eli3_bd_logic_empty_desc">' +
        'This document does not contain ELI template logic.<br>' +
        'Open a template with <code>{{DEF:...}}</code> and <code>{{IF:...}}</code> tags.' +
      '</div>' +
      '<button class="_eli3_bd_run_all _eli3_bd_logic_oars_btn">SCAN FOR OARS DATA</button>';
    root.appendChild(empty);
    empty.querySelector("._eli3_bd_logic_oars_btn").onclick = onScanForOars;
    mount.appendChild(root);
    return;
  }

  var form = document.createElement("div");
  form.className = "_eli3_bd_logic_form";

  function _renderInputs() {
    form.innerHTML = "";
    keys.forEach(function (key) {
      var def = defs[key];
      var group = document.createElement("div");
      group.className = "_eli3_bd_logic_group";
      group.setAttribute("data-key", key);
      var labelHtml = '<span>' + _esc(key) + '</span>' +
        (def.warning ? '<span class="_eli3_bd_logic_warning">⚠️ ' + _esc(def.warning) + '</span>' : '');
      group.innerHTML = '<label class="_eli3_bd_logic_label">' + labelHtml + '</label>';
      if (def.isText) {
        var hint = document.createElement("div");
        hint.className = "_eli3_bd_logic_hint";
        hint.textContent = "Free Form Entry — leave as 'Don't know' if not sure.";
        group.appendChild(hint);
        var inp = document.createElement("input");
        inp.type = "text";
        inp.className = "_eli3_bd_logic_input";
        inp.value = def.default || "";
        inp.placeholder = "Enter " + key + "…";
        inp.setAttribute("data-key", key);
        inp.oninput = _updateVisibility;
        group.appendChild(inp);
      } else {
        var sel = document.createElement("select");
        sel.className = "_eli3_bd_logic_input";
        sel.setAttribute("data-key", key);
        def.options.forEach(function (opt) {
          var o = document.createElement("option");
          o.value = opt; o.textContent = opt;
          if (opt === def.default) o.selected = true;
          sel.appendChild(o);
        });
        sel.onchange = _updateVisibility;
        group.appendChild(sel);
      }
      form.appendChild(group);
    });
  }

  // Single canonical evaluator from engine; opts.evalCondition wins
  // (init wires the bundle helper through), else fall back to inline.
  var _evalCondition = opts.evalCondition || function (cond, ans) {
    if (cond === "true") return true;
    var op = cond.indexOf("!=") !== -1 ? "!=" : "==";
    var parts = cond.split(op);
    if (parts.length < 2) return false;
    var k = parts[0].trim();
    var rhs = parts[1].split("||").map(function (t) { return t.trim().replace(/['"]/g, ""); });
    var actual = ans && ans[k];
    if (actual === undefined) return false;
    return op === "==" ? rhs.indexOf(actual) !== -1 : rhs.indexOf(actual) === -1;
  };
  function _updateVisibility() {
    var answers = {};
    form.querySelectorAll("._eli3_bd_logic_input").forEach(function (i) {
      answers[i.getAttribute("data-key")] = i.value;
    });
    Object.keys(deps).forEach(function (key) {
      var rules = deps[key] || [];
      var visible = rules.every(function (r) { return _evalCondition(r, answers); });
      var grp = form.querySelector('._eli3_bd_logic_group[data-key="' + key + '"]');
      if (grp) grp.style.display = visible ? "block" : "none";
    });
  }

  _renderInputs();
  root.appendChild(form);

  var actions = document.createElement("div");
  actions.className = "_eli3_bd_logic_actions";
  var gen = document.createElement("button");
  gen.className = "_eli3_bd_run_all";
  gen.innerHTML = "🚀 GENERATE DOCUMENT";
  gen.onclick = function () {
    var answers = {};
    form.querySelectorAll("._eli3_bd_logic_input").forEach(function (i) {
      answers[i.getAttribute("data-key")] = i.value;
    });
    onGenerate(answers);
  };
  actions.appendChild(gen);
  root.appendChild(actions);

  mount.appendChild(root);
  _updateVisibility();
}

// renderTemplateFillForm — Step 2 v3 port of v2 renderTemplateForm (line 6458).
// Lists placeholders with auto-expanding textareas + Locate buttons +
// optional AI Auto-Fill button when AGREEMENT_DATA is loaded.

view.renderTemplateFillForm:
function renderTemplateFillForm(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var placeholders = opts.placeholders || [];
  var sourceText = opts.sourceText || "";
  var sourceName = opts.sourceName || null;
  var onAutoFill = opts.onAutoFill || function () {};
  var onApply = opts.onApply || function () {};
  var onLocate = opts.onLocate || function () {};
  var onUpload = opts.onUpload || function () {};
  var onBack = opts.onBack || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _cleanLabel(ph) {
    var raw = ph.replace(/[\[\]{}]/g, "").replace(/^(\$!|\$|!)/, "");
    if (raw.indexOf("||") !== -1) {
      var parts = raw.split("||");
      return { label: parts[1].trim(), aiKey: parts[0].trim() };
    }
    return { label: raw, aiKey: raw };
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_fill";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">⚡ Auto-Fill Templates</div>' +
      '<div class="_eli3_bd_overview">' + placeholders.length + ' placeholder' + (placeholders.length === 1 ? "" : "s") + '</div>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;

  if (!placeholders.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_fill_empty";
    empty.innerHTML =
      '<b>No placeholders detected.</b><br>Open a template with <code>[[Brackets]]</code>.';
    root.appendChild(empty);
    mount.appendChild(root);
    return;
  }

  // AGREEMENT data summary + Auto-Fill button if loaded
  if (sourceText) {
    var loaded = document.createElement("div");
    loaded.className = "_eli3_bd_fill_loaded";
    loaded.innerHTML =
      '<div class="_eli3_bd_fill_loaded_main">' +
        '<div class="_eli3_bd_fill_loaded_label">LOADED SOURCE</div>' +
        '<div class="_eli3_bd_fill_loaded_name">📄 ' + _esc(sourceName || "OARS data") + '</div>' +
      '</div>' +
      '<button class="_eli3_bd_fill_autofill_btn">⚡ AUTO-FILL</button>' +
      '<div class="_eli3_bd_fill_status" hidden></div>';
    root.appendChild(loaded);
    var autoBtn = loaded.querySelector("._eli3_bd_fill_autofill_btn");
    var status = loaded.querySelector("._eli3_bd_fill_status");
    autoBtn.onclick = function () {
      autoBtn.disabled = true;
      autoBtn.textContent = "⏳ Filling…";
      status.hidden = false;
      status.textContent = "Analyzing data…";
      onAutoFill(placeholders, function (mapping, err) {
        autoBtn.disabled = false;
        autoBtn.textContent = "⚡ AUTO-FILL";
        if (err) { status.textContent = "❌ " + (err.message || "Error"); return; }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        var missing = inputs.length - filled;
        status.textContent = "✅ Filled " + filled + " · ❌ Missing " + missing;
      });
    };
  } else {
    // No source loaded — drop-zone for .docx/.txt/.csv/.json
    var dropZone = document.createElement("div");
    dropZone.className = "_eli3_bd_fill_drop";
    dropZone.innerHTML =
      '<div class="_eli3_bd_fill_drop_icon">📂</div>' +
      '<div class="_eli3_bd_fill_drop_title">Import Data Source</div>' +
      '<div class="_eli3_bd_fill_drop_desc">Click to upload (.docx, .txt, .csv, .json)</div>';
    var fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = ".docx,.txt,.csv,.json,application/pdf";
    fileInput.style.display = "none";
    dropZone.onclick = function () { fileInput.click(); };
    fileInput.onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (!f) return;
      dropZone.innerHTML =
        '<div class="_eli3_bd_fill_drop_icon">⏳</div>' +
        '<div class="_eli3_bd_fill_drop_title">Reading ' + _esc(f.name) + '…</div>';
      onUpload(f, placeholders, function (mapping, err) {
        if (err) {
          dropZone.innerHTML =
            '<div class="_eli3_bd_fill_drop_icon">❌</div>' +
            '<div class="_eli3_bd_fill_drop_title">' + _esc(err.message || "Error") + '</div>';
          return;
        }
        var inputs = root.querySelectorAll("._eli3_bd_fill_input");
        var filled = 0;
        inputs.forEach(function (inp) {
          var v = mapping[inp.dataset.target] || mapping[inp.dataset.aiKey];
          inp.classList.remove("_bd_filled", "_bd_missing");
          if (v) {
            inp.value = v;
            inp.classList.add("_bd_filled");
            filled++;
            inp.style.height = "auto";
            inp.style.height = inp.scrollHeight + "px";
          } else {
            inp.classList.add("_bd_missing");
          }
        });
        dropZone.innerHTML =
          '<div class="_eli3_bd_fill_drop_icon">✅</div>' +
          '<div class="_eli3_bd_fill_drop_title">Filled ' + filled + ' / ' + inputs.length + ' fields</div>';
      });
    };
    root.appendChild(dropZone);
    root.appendChild(fileInput);
  }

  // Per-placeholder fill rows
  var formContainer = document.createElement("div");
  formContainer.className = "_eli3_bd_fill_form";
  placeholders.forEach(function (ph) {
    var ck = _cleanLabel(ph);
    var wrap = document.createElement("div");
    wrap.className = "_eli3_bd_fill_field";
    wrap.innerHTML =
      '<label class="_eli3_bd_fill_label">' +
        '<span>' + _esc(ck.label) + '</span>' +
        '<button class="_eli3_bd_fill_locate" type="button" title="Locate in document">📍 Locate</button>' +
      '</label>';
    var inp = document.createElement("textarea");
    inp.className = "_eli3_bd_fill_input";
    inp.dataset.target = ph;
    inp.dataset.aiKey = ck.aiKey;
    inp.placeholder = "Enter " + ck.label;
    inp.rows = 1;
    inp.addEventListener("input", function () {
      this.style.height = "auto";
      this.style.height = this.scrollHeight + "px";
    });
    wrap.appendChild(inp);
    var locBtn = wrap.querySelector("._eli3_bd_fill_locate");
    locBtn.onclick = function () { onLocate(ph, inp.value); };
    formContainer.appendChild(wrap);
  });
  root.appendChild(formContainer);

  var actions = document.createElement("div");
  actions.className = "_eli3_bd_logic_actions";
  var apply = document.createElement("button");
  apply.className = "_eli3_bd_run_all";
  apply.innerHTML = "FILL ALL FIELDS";
  apply.onclick = function () {
    var values = {};
    formContainer.querySelectorAll("._eli3_bd_fill_input").forEach(function (inp) {
      values[inp.dataset.target] = inp.value;
    });
    onApply(values);
  };
  actions.appendChild(apply);
  root.appendChild(actions);

  mount.appendChild(root);
}

// renderBracketCleaner — Step 2 v3-native port of v2's showBracketCleaner
// (line 22706). Lists [bracket] placeholders + locate buttons + 💡 SOW
// helper trigger when a cleaner_rules match exists.

view.renderBracketCleaner:
function renderBracketCleaner(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var brackets = (opts.brackets && opts.brackets.items) || [];
  var financial = (opts.financial && opts.financial.items) || [];
  var cleanerRules = opts.cleanerRules || [];
  var onBack = opts.onBack || function () {};
  var onLocate = opts.onLocate || function () {};
  var onSowHelper = opts.onSowHelper || function () {};
  var onDone = opts.onDone || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Find a cleaner_rules match for an inner bracket label.
  function _ruleFor(inner) {
    var lower = String(inner || "").toLowerCase();
    for (var i = 0; i < cleanerRules.length; i++) {
      var r = cleanerRules[i];
      if (!r || !r.id || r.id.indexOf("__") === 0) continue;
      if (lower.indexOf(String(r.id).toLowerCase()) !== -1) return r;
      if (r.title && lower.indexOf(String(r.title).toLowerCase().replace(/[^a-z]/g, "")) !== -1) return r;
    }
    return null;
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_cleaner";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">📝 Fill Placeholders</div>' +
      '<div class="_eli3_bd_overview">' + brackets.length + ' bracket' + (brackets.length === 1 ? "" : "s") +
        (financial.length ? ' · ' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") : '') +
      '</div>' +
    '</div>' +
    '<div class="_eli3_bd_cleaner_intro">' +
      (brackets.length || financial.length
        ? '<b>' + brackets.length + ' placeholder' + (brackets.length === 1 ? "" : "s") + '</b> + ' +
          '<b>' + financial.length + ' $ amount' + (financial.length === 1 ? "" : "s") + '</b> detected. ' +
          'Use Locate to jump to each in Word; click 💡 for SOW Helper suggestions when available.'
        : 'No placeholders or $ amounts detected in the body.') +
    '</div>' +
    '<div class="_eli3_bd_cleaner_list" id="_eli3_bd_cleaner_list"></div>' +
    '<div class="_eli3_bd_cleaner_done">' +
      '<button class="_eli3_bd_run_all" id="_eli3_bd_done_btn">I\'M DONE ➜</button>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("#_eli3_bd_done_btn").onclick = onDone;

  var list = root.querySelector("#_eli3_bd_cleaner_list");
  // Combined list: brackets first, $ amounts after.
  var rows = brackets.map(function (b) { return { type: "bracket", text: b.text, inner: b.inner, rule: _ruleFor(b.inner) }; })
    .concat(financial.map(function (f) { return { type: "financial", text: f.text, inner: f.text }; }));
  if (!rows.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_bd_cleaner_empty";
    empty.textContent = "Nothing to review.";
    list.appendChild(empty);
  } else {
    rows.forEach(function (r, idx) {
      var row = document.createElement("div");
      row.className = "_eli3_bd_cleaner_row";
      var typeTag = r.type === "financial"
        ? '<span class="_eli3_bd_cleaner_tag _eli3_bd_cleaner_tag_money">$</span>'
        : '<span class="_eli3_bd_cleaner_tag">[</span>';
      var helperBtn = r.rule
        ? '<button class="_eli3_bd_action_btn _eli3_bd_action_help" data-eli-bd-help="' + idx + '">💡 Suggestions</button>'
        : '';
      row.innerHTML =
        '<div class="_eli3_bd_cleaner_left">' +
          typeTag +
          '<span class="_eli3_bd_cleaner_text">' + _esc(r.text) + '</span>' +
        '</div>' +
        '<div class="_eli3_bd_cleaner_right">' +
          '<button class="_eli3_bd_action_btn _eli3_bd_action_locate" data-eli-bd-locate="' + idx + '">📍 Locate</button>' +
          helperBtn +
        '</div>';
      row.querySelector("[data-eli-bd-locate]").onclick = function () { onLocate(r); };
      var help = row.querySelector("[data-eli-bd-help]");
      if (help) help.onclick = function () { onSowHelper(r); };
      list.appendChild(row);
    });
  }
  mount.appendChild(root);
}

// renderSowHelper — modal overlay listing cleaner_rules options for a
// detected bracket. FROM v2 showGenericCleanerHelper (line 22780).
// Uses showEliDialog for tier:premium consistency.

view.renderSowHelper:
function renderSowHelper(opts) {
  var rule = opts.rule || {};
  var target = opts.target || "";
  var onPick = opts.onPick || function () {};
  if (typeof showEliDialog !== "function") {
    if (window.eli && window.eli.log) window.eli.log.event("tool", "build_draft_no_dialog", {});
    if (typeof showToast === "function") showToast("Dialog primitive unavailable", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  var optsHtml = (rule.options || []).map(function (o, i) {
    return '<button class="_eli3_bd_sow_option" data-eli-bd-sow-pick="' + i + '">' +
      '<span class="_eli3_bd_sow_option_label">' + _esc(o.label) + '</span>' +
      '<span class="_eli3_bd_sow_option_desc">' + _esc(o.desc || o.text || "") + '</span>' +
    '</button>';
  }).join("");
  showEliDialog({
    variant: "info",
    tier: "premium",
    icon: "💡",
    title: "SOW Helper · " + (rule.title || rule.id || "Suggestions"),
    body:
      '<div class="_eli3_bd_sow_intro">Select a clause to replace ' +
      '<b>' + _esc(target) + '</b>:</div>' +
      '<div class="_eli3_bd_sow_options">' + optsHtml + '</div>',
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      overlay.querySelectorAll("[data-eli-bd-sow-pick]").forEach(function (btn) {
        btn.onclick = function () {
          var i = parseInt(btn.getAttribute("data-eli-bd-sow-pick"), 10);
          var picked = (rule.options || [])[i];
          if (picked) onPick(picked);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

// renderTemplatesView — FROM v2 showFileNameSettings (line 20740). Two
// tabs: FILE NAMING (pattern config + highlight toggle) and XML
// TEMPLATES (per-agreement-type library + active-doc save + bulk
// import/export + per-row Load/Delete).

view.renderTemplatesView:
function renderTemplatesView(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initialTab = opts.tab || "templates"; // "naming" | "templates"
  var patterns = opts.patterns || {
    colgate: "[Ref] - CP-[Party] -- [Type] (DRAFT [Date])",
    hills: "[Ref] - HPN-[Party] -- [Type] (DRAFT [Date])",
  };
  var highlightFill = !!opts.highlightFill;
  var templates = opts.templates || [];
  var onSavePatterns = opts.onSavePatterns || function () {};
  var onSaveActiveDoc = opts.onSaveActiveDoc || function () {};
  var onLoadTemplate = opts.onLoadTemplate || function () {};
  var onDeleteTemplate = opts.onDeleteTemplate || function () {};
  var onBulkImport = opts.onBulkImport || function () {};
  var onBack = opts.onBack || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_tpl";
  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">⚙️ Build Draft Settings</div>' +
      '<div class="_eli3_bd_overview">' + templates.length + ' template' + (templates.length === 1 ? "" : "s") + '</div>' +
    '</div>' +
    '<div class="_eli3_bd_tpl_tabs">' +
      '<button class="_eli3_bd_tpl_tab" data-tab="naming">FILE NAMING</button>' +
      '<button class="_eli3_bd_tpl_tab" data-tab="templates">XML TEMPLATES</button>' +
    '</div>' +
    '<div class="_eli3_bd_tpl_body" id="_eli3_bd_tpl_body"></div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  var body = root.querySelector("#_eli3_bd_tpl_body");

  function _setActiveTab(name) {
    root.querySelectorAll("._eli3_bd_tpl_tab").forEach(function (t) {
      t.classList.toggle("_eli3_bd_tpl_tab_active", t.getAttribute("data-tab") === name);
    });
    if (name === "naming") _renderNaming();
    else _renderTemplates();
  }
  root.querySelectorAll("._eli3_bd_tpl_tab").forEach(function (t) {
    t.onclick = function () { _setActiveTab(t.getAttribute("data-tab")); };
  });

  function _renderNaming() {
    body.innerHTML =
      '<div class="_eli3_bd_tpl_hint">' +
        '<b>Tokens:</b> <code>[Ref]</code> <code>[Party]</code> <code>[Type]</code> <code>[Date]</code>' +
      '</div>' +
      '<label class="_eli3_bd_tpl_label">Colgate Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_colgate" class="_eli3_bd_tpl_input" value="' + _esc(patterns.colgate) + '">' +
      '<label class="_eli3_bd_tpl_label">Hill\'s Pattern</label>' +
      '<input type="text" id="_eli3_bd_pat_hills" class="_eli3_bd_tpl_input" value="' + _esc(patterns.hills) + '">' +
      '<label class="_eli3_bd_tpl_check">' +
        '<input type="checkbox" id="_eli3_bd_chk_highlight"' + (highlightFill ? " checked" : "") + '>' +
        '<span>🖊️ Highlight filled fields</span>' +
      '</label>' +
      '<button class="_eli3_bd_run_all" id="_eli3_bd_save_naming">SAVE PATTERNS</button>';
    body.querySelector("#_eli3_bd_save_naming").onclick = function () {
      onSavePatterns({
        patterns: {
          colgate: body.querySelector("#_eli3_bd_pat_colgate").value,
          hills: body.querySelector("#_eli3_bd_pat_hills").value,
        },
        highlightFill: body.querySelector("#_eli3_bd_chk_highlight").checked,
      });
    };
  }

  function _renderTemplates() {
    body.innerHTML =
      '<div class="_eli3_bd_tpl_hint">Save the active document as a reusable template per agreement type.</div>' +
      '<div class="_eli3_bd_tpl_save">' +
        '<div class="_eli3_bd_tpl_save_label">FROM ACTIVE DOCUMENT</div>' +
        '<div class="_eli3_bd_tpl_save_radios">' +
          '<label><input type="radio" name="_eli3_bd_cat" value="MasterXML" checked> 🏗️ Core Template</label>' +
          '<label><input type="radio" name="_eli3_bd_cat" value="PriorAgreement"> 📂 Prior Agreement</label>' +
        '</div>' +
        '<input type="text" id="_eli3_bd_tpl_type" class="_eli3_bd_tpl_input" placeholder="Agreement Type (e.g. MSA Template)">' +
        '<input type="text" id="_eli3_bd_tpl_party" class="_eli3_bd_tpl_input _eli3_bd_tpl_hidden" placeholder="Party Name (Required for Prior Agreement)">' +
        '<button class="_eli3_bd_run_all" id="_eli3_bd_tpl_save_btn">💾 Save Active Doc as Template</button>' +
      '</div>' +
      '<div class="_eli3_bd_tpl_label">Saved Templates</div>' +
      '<div class="_eli3_bd_tpl_list" id="_eli3_bd_tpl_list"></div>' +
      '<div class="_eli3_bd_tpl_bulk">' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_import">⬆️ Import JSON</button>' +
        '<input type="file" id="_eli3_bd_tpl_import_file" accept=".json" hidden>' +
        '<button class="_eli3_bd_tpl_bulk_btn" id="_eli3_bd_tpl_export">⬇️ Export All</button>' +
      '</div>';

    body.querySelectorAll('input[name="_eli3_bd_cat"]').forEach(function (radio) {
      radio.addEventListener("change", function () {
        var partyInp = body.querySelector("#_eli3_bd_tpl_party");
        partyInp.classList.toggle("_eli3_bd_tpl_hidden", this.value !== "PriorAgreement");
      });
    });
    body.querySelector("#_eli3_bd_tpl_save_btn").onclick = function () {
      var typeVal = body.querySelector("#_eli3_bd_tpl_type").value.trim();
      var partyVal = body.querySelector("#_eli3_bd_tpl_party").value.trim();
      var category = body.querySelector('input[name="_eli3_bd_cat"]:checked').value;
      if (!typeVal) { if (typeof showToast === "function") showToast("Enter an Agreement Type", "warn"); return; }
      if (category === "PriorAgreement" && !partyVal) {
        if (typeof showToast === "function") showToast("Prior Agreement requires a Party Name", "warn");
        return;
      }
      this.disabled = true;
      this.innerText = "⏳ Scanning…";
      onSaveActiveDoc({ type: typeVal, party: partyVal, category: category });
    };
    body.querySelector("#_eli3_bd_tpl_import").onclick = function () {
      body.querySelector("#_eli3_bd_tpl_import_file").click();
    };
    body.querySelector("#_eli3_bd_tpl_import_file").onchange = function (e) {
      var f = e.target.files && e.target.files[0];
      if (f) onBulkImport(f);
    };
    body.querySelector("#_eli3_bd_tpl_export").onclick = function () {
      var json = JSON.stringify(templates, null, 2);
      try {
        navigator.clipboard.writeText(json);
        if (typeof showToast === "function") showToast("📋 " + templates.length + " templates copied to clipboard", "ok");
      } catch (err) {
        if (typeof showToast === "function") showToast("Copy failed: " + (err && err.message), "err");
      }
    };

    var list = body.querySelector("#_eli3_bd_tpl_list");
    if (!templates.length) {
      list.innerHTML = '<div class="_eli3_bd_tpl_empty">No templates saved yet.</div>';
      return;
    }
    var sorted = templates.slice().sort(function (a, b) { return a.type === "MasterXML" ? -1 : 1; });
    list.innerHTML = "";
    sorted.forEach(function (t) {
      var isCore = t.type === "MasterXML";
      var icon = isCore ? "🏗️" : "📂";
      var badge = isCore ? "CORE" : "PRIOR";
      var size = (String(t.content || "").length / 1024).toFixed(1);
      var row = document.createElement("div");
      row.className = "_eli3_bd_tpl_row " + (isCore ? "_eli3_bd_tpl_row_core" : "_eli3_bd_tpl_row_prior");
      row.innerHTML =
        '<div class="_eli3_bd_tpl_row_main">' +
          '<div class="_eli3_bd_tpl_row_name">' + icon + " " + _esc(t.name || t.agreementType || "Untitled") + '</div>' +
          '<div class="_eli3_bd_tpl_row_meta">' + badge + ' · ' + size + ' KB · ' + _esc(t.savedDate || "") + '</div>' +
        '</div>' +
        '<button class="_eli3_bd_tpl_row_load" title="Load into doc">📥</button>' +
        '<button class="_eli3_bd_tpl_row_del" title="Delete">🗑️</button>';
      row.querySelector("._eli3_bd_tpl_row_load").onclick = function () { onLoadTemplate(t); };
      row.querySelector("._eli3_bd_tpl_row_del").onclick = function () { onDeleteTemplate(t); };
      list.appendChild(row);
    });
  }

  _setActiveTab(initialTab);
  mount.appendChild(root);
}

// renderSavePanel — FROM v2 showSaveAsManager (line 18930). Step 4
