  };
  var onSave = opts.onSave || function () {};
  var onSkip = opts.onSkip || function () {};
  var onSettings = opts.onSettings || function () {};
  var onBack = opts.onBack || function () {};
  var scanning = !!opts.scanning;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_bd_root _eli3_bd_save";

  var typeOpts = '<option value="Other">Other (type below)</option>' +
    agTypes.map(function (t) { return '<option value="' + _esc(t) + '">' + _esc(t) + '</option>'; }).join("");

  root.innerHTML =
    '<div class="_eli3_bd_bar">' +
      '<button class="_eli3_bd_back">←</button>' +
      '<div class="_eli3_bd_title">💾 Save Document</div>' +
      '<button class="_eli3_bd_save_settings" title="File-name settings">⚙️</button>' +
    '</div>' +
    (scanning
      ? '<div class="_eli3_bd_save_scanloader">' +
          '<div class="_eli3_bd_save_spinner"></div>' +
          '<div>Scanning document for metadata…</div>' +
        '</div>'
      : '') +
    '<div class="_eli3_bd_save_form">' +
      '<label class="_eli3_bd_save_label">CP Contracting Entity</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_entity">' +
        '<option value="Colgate">Colgate-Palmolive Company</option>' +
        '<option value="Hills">Hill\'s Pet Nutrition</option>' +
      '</select>' +
      '<label class="_eli3_bd_save_label">Agreement Type</label>' +
      '<select class="_eli3_bd_save_input" id="_eli3_bd_save_type">' + typeOpts + '</select>' +
      '<input type="text" class="_eli3_bd_save_input _eli3_bd_save_hidden" id="_eli3_bd_save_typeManual" placeholder="Type Agreement Name…">' +
      '<label class="_eli3_bd_save_label">Third Party Name</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_party" placeholder="e.g. Acme Corp">' +
      '<label class="_eli3_bd_save_label">CP Ref #</label>' +
      '<input type="text" class="_eli3_bd_save_input" id="_eli3_bd_save_ref" placeholder="e.g. 12345">' +
      '<div class="_eli3_bd_save_preview">' +
        '<span class="_eli3_bd_save_preview_label">Preview Filename:</span>' +
        '<span class="_eli3_bd_save_preview_value" id="_eli3_bd_save_preview">…</span>' +
      '</div>' +
      '<button class="_eli3_bd_run_all" id="_eli3_bd_save_btn">💾 Save Document</button>' +
      '<button class="_eli3_bd_save_skip" id="_eli3_bd_save_skip">Skip — Done</button>' +
    '</div>';
  root.querySelector("._eli3_bd_back").onclick = onBack;
  root.querySelector("._eli3_bd_save_settings").onclick = onSettings;

  var entitySel = root.querySelector("#_eli3_bd_save_entity");
  var typeSel = root.querySelector("#_eli3_bd_save_type");
  var typeManual = root.querySelector("#_eli3_bd_save_typeManual");
  var partyInp = root.querySelector("#_eli3_bd_save_party");
  var refInp = root.querySelector("#_eli3_bd_save_ref");
  var previewEl = root.querySelector("#_eli3_bd_save_preview");

  // Apply prefill.
  if (prefill.entity) entitySel.value = prefill.entity;
  if (prefill.third_party_entity) partyInp.value = prefill.third_party_entity;
  if (prefill.cp_ref) refInp.value = prefill.cp_ref;
  // Match agreement type by case-insensitive substring.
  var prefType = (prefill.type || "").toLowerCase();
  if (prefType) {
    var found = false;
    for (var i = 0; i < typeSel.options.length; i++) {
      var v = typeSel.options[i].value.toLowerCase();
      if (v && v !== "other" && (prefType.indexOf(v) !== -1 || v.indexOf(prefType) !== -1)) {
        typeSel.selectedIndex = i; found = true; break;
      }
    }
    if (!found) {
      typeSel.value = "Other";
      typeManual.classList.remove("_eli3_bd_save_hidden");
      typeManual.value = prefill.type;
    }
  }

  function _genName() {
    var entity = entitySel.value;
    var type = typeSel.value === "Other" ? (typeManual.value || "Agreement") : typeSel.value;
    var party = partyInp.value.trim() || "Unknown";
    var ref = refInp.value.trim() || "Draft";
    var d = new Date();
    var date = (d.getMonth() + 1).toString().padStart(2, "0") + "."
             + d.getDate().toString().padStart(2, "0") + "."
             + d.getFullYear();
    var pat = entity === "Hills" ? patterns.hills : patterns.colgate;
    return pat.replace("[Ref]", ref).replace("[Party]", party).replace("[Type]", type).replace("[Date]", date) + ".docx";
  }
  function _updatePreview() { previewEl.textContent = _genName(); }

  typeSel.onchange = function () {
    typeManual.classList.toggle("_eli3_bd_save_hidden", typeSel.value !== "Other");
    _updatePreview();
  };
  [entitySel, typeManual, partyInp, refInp].forEach(function (el) {
    el.addEventListener("input", _updatePreview);
    el.addEventListener("change", _updatePreview);
  });
  _updatePreview();

  root.querySelector("#_eli3_bd_save_btn").onclick = function () {
    onSave({
      entity: entitySel.value,
      type: typeSel.value === "Other" ? (typeManual.value || "Agreement") : typeSel.value,
      third_party_entity: partyInp.value.trim(),
      cp_ref: refInp.value.trim(),
      filename: _genName(),
    });
  };
  root.querySelector("#_eli3_bd_save_skip").onclick = onSkip;

  mount.appendChild(root);
}

view.renderStepStub:
function renderStepStub(opts) {
