jsonTools.init:
function init(eli) {
  // Magic-string constants — single source of truth across this tool.
  var SETTINGS_NAME = "AgreementDataName";
  var SETTINGS_TYPE = "AgreementDataType";
  var SETTINGS_DETAILS = "AgreementDataDetails";
  var BUS_OARS_FILE = "oars:file_selected";
  var BUS_OARS_CLEARED = "oars:cleared";
  var BUS_OARS_DETECTED = "oars:detected";
  var HF_TYPES = HF_TYPES;
  var STEP2_APPLY_BATCH = 4; // keys per runRaw to keep under 100ms.

  // Wizard mode flag: when true, Step 1 → Step 2 → preSave → Step 3
  // chain auto-advances. Toggled by Run-All; cleared after Step 3 fires.
  var _wizardMode = false;

  // Kernel guarantees eli.events; if it's missing the kernel itself is
  // broken — fail loudly rather than paper over with a no-op shim.
  if (!eli.events || !eli.events.guard || !eli.events.safeAsync) {
    if (eli.log) eli.log.event("tool", "build_draft_missing_events", {});
    if (typeof showToast === "function") showToast("Build Draft failed: kernel events missing", "err");
    return;
  }
  var bundle = eli.tools._loaded["build_draft"];
  if (!bundle) return;
  var engineFns = bundle._eliEngineFns || {};
  var viewFns = bundle._eliViewFns || {};
  var analyze = engineFns.analyze;
  var evalLogicCondition = engineFns.evalLogicCondition;
  var extractTemplatePlaceholders = engineFns.extractTemplatePlaceholders;
  var renderHub = viewFns.renderHub;
  var renderStepStub = viewFns.renderStepStub;
  var renderBracketCleaner = viewFns.renderBracketCleaner;
  var renderSowHelper = viewFns.renderSowHelper;
  var renderLogicForm = viewFns.renderLogicForm;
  var renderTemplateFillForm = viewFns.renderTemplateFillForm;
  var renderTemplatesView = viewFns.renderTemplatesView;
  var renderSavePanel = viewFns.renderSavePanel;
  if (!analyze || !renderHub) {
    eli.log.event("tool", "build_draft_load_failed", { hasEngine: !!analyze, hasView: !!renderHub });
    return;
  }

  var providers = { host: eli.host, ai: eli.ai };

  // Footer-uploaded file cache. Kernel's status-bar DATA loader emits
  // "oars:file_selected" with {name, size, text}. Cache here so analyze()
  // sees the file contents on next render. FROM v2 finishFooterLoad
  // (line 14447) which set window.AGREEMENT_DATA = {name, text}.
  var _footerFile = null;
  if (eli.bus && eli.bus.on) {
    eli.bus.on(BUS_OARS_FILE, function (payload) {
      _footerFile = payload ? {
        name: payload.name,
        size: payload.size,
        text: payload.text || "",
        // FROM v2 AGREEMENT_DATA shape — PDFs travel as base64 inline
        // data so eli.ai can pass them to Gemini's PDF reader.
        isBase64: !!payload.isBase64,
        mime: payload.mime || null,
        data: payload.data || null,
      } : null;
      // Pre-warm AI cache in the background (matches v2 finishFooterLoad
      // → runBackgroundAIAnalysis chain). Best-effort; failures are
      // logged but don't surface to the user.
      if (_footerFile && _footerFile.text) {
        _runBackgroundAIAnalysis(_footerFile.text);
      }
      var mount = document.getElementById("_eli3_dashboard_root");
      if (mount && mount.querySelector("._eli3_bd_root")) _show({ source: "footer_file" });
    });
    eli.bus.on(BUS_OARS_CLEARED, function () {
      _footerFile = null;
      var mount = document.getElementById("_eli3_dashboard_root");
      if (mount && mount.querySelector("._eli3_bd_root")) _show({ source: "footer_clear" });
    });
  }

  // Word.run: scan body + headers for OARS prefix; return text for parsing.
  function _scanDocForOars() {
    return eli.host.runRaw("build_draft:oars_scan", function (context) {
      var body = context.document.body;
      var section = context.document.sections.getFirst();
      var primaryHeader = section.getHeader("Primary");
      var firstHeader = section.getHeader("FirstPage");
      primaryHeader.load("text");
      firstHeader.load("text");
      body.load("text");
      return context.sync().then(function () {
        var headerText = ((primaryHeader.text || "") + " " + (firstHeader.text || "")).trim();
        var bodyText = body.text || "";
        var found = /\bOARS\b/i.test(headerText) || /\bOARS\b/i.test(bodyText);
        return { found: found, bodyText: bodyText, headerText: headerText };
      });
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_scan_failed", { error: err && err.message });
      return { found: false, bodyText: "", headerText: "" };
    });
  }

  // Step 2 scan: gather text from body + every header/footer type so the
  // placeholder set covers the whole doc. FROM v2 runTemplateScan (6404).
  function _scanForFill() {
    return eli.host.runRaw("build_draft:fill_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var ranges = [body];
        sections.items.forEach(function (sec) {
          HF_TYPES.forEach(function (t) {
            try { ranges.push(sec.getHeader(t)); }
            catch (e) { eli.log.event("tool", "build_draft_header_skip", { type: t, msg: e && e.message }); }
            try { ranges.push(sec.getFooter(t)); }
            catch (e) { eli.log.event("tool", "build_draft_footer_skip", { type: t, msg: e && e.message }); }
          });
        });
        ranges.forEach(function (r) { r.load("text"); });
        return context.sync().then(function () {
          var fullText = "";
          ranges.forEach(function (r) { fullText += (r.text || "") + "\n"; });
          return fullText;
        });
      });
    }).catch(function () { return ""; });
  }

  // === AI cache layer (FROM v2 PROMPTS.saveAICacheToDB / saveDocToDB) ===
  // Caches per-source AI extraction so re-opens skip the AI call. Keyed
  // by a content hash so cache bust is automatic when source text changes.
  // Stored in STORE_CONFIG with id "_bd_ai_cache_<hash>" — leading "_"
  // marks it as kernel-internal (skipped by tool listings).
  function _bd_hashContent(text) {
    var s = String(text || "");
    var h = 0;
    for (var i = 0; i < s.length; i++) {
      h = ((h << 5) - h) + s.charCodeAt(i);
      h |= 0;
    }
    return "h" + (h >>> 0).toString(16);
  }

  function _bd_aiCacheKey(text) {
    return "_bd_ai_cache_" + _bd_hashContent(text);
  }

  function _bd_aiCacheGet(text) {
    var key = _bd_aiCacheKey(text);
    return eli.storage.get("config", key)
      .then(function (row) {
        if (row && row.value && Date.now() - (row.cachedAt || 0) < 7 * 24 * 60 * 60 * 1000) return row.value;
        return null;
      })
      .catch(function () { return null; });
  }

  function _bd_aiCachePut(text, value) {
    var key = _bd_aiCacheKey(text);
    return eli.storage.put("config", { id: key, value: value, cachedAt: Date.now() })
      .catch(function (e) {
        eli.log.event("tool", "build_draft_ai_cache_put_failed", { msg: e && e.message });
      });
  }

  // FROM v2 PROMPTS.runBackgroundAIAnalysis (line 1585). Pre-warms the
  // AI fill cache when OARS data loads so the user's Step 2 click is
  // instant. No-op if cache already populated for this content.
  function _runBackgroundAIAnalysis(sourceText) {
    if (!sourceText || sourceText.length < 50) return Promise.resolve(null);
    return _bd_aiCacheGet(sourceText).then(function (cached) {
      if (cached) {
        eli.log.event("tool", "build_draft_ai_prewarm_hit", {});
        return cached;
      }
      // Best-effort generic field extraction. The Step 2 fill flow uses
      // its own templateMap prompt for placeholder-specific mapping; this
      // pre-warms a broader field/data list for fast re-use.
      var prompt =
        "Analyze this document content.\n" +
        "TASK: Extract pairs of Field (Left) and Data (Right) from the document.\n" +
        "RETURN JSON ARRAY: [ { \"field\": \"...\", \"data\": \"...\" } ]\n" +
        "- Exclude rows where \"Data\" is empty.\n" +
        "- For tabular docs, Left col = Field, Right col = Data.\n\n" +
        "--- DOCUMENT ---\n" + sourceText;
      return eli.events.safeAsync(eli.ai.completeJSON(prompt, null, { maxTokens: 4000 }), "build_draft.prewarm")
        .then(function (json) {
          if (Array.isArray(json) && json.length) {
            return _bd_aiCachePut(sourceText, json).then(function () { return json; });
          }
          return null;
        })
        .catch(function (e) {
          eli.log.event("tool", "build_draft_ai_prewarm_failed", { msg: e && e.message });
          return null;
        });
    });
  }

  // FROM v2 persistAgreementState (line 14463). Saves type/name/details
  // into Office settings so future scans see the loaded state.
  function _persistAgreementState(name, type, details) {
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      if (name) s.set(SETTINGS_NAME, name);
      if (type) s.set(SETTINGS_TYPE, type);
      if (details) s.set(SETTINGS_DETAILS, details);
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_persist_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // Full OARS clear: delegate to kernel so ALL OARS keys are removed
  // (kernel's Name/Text/Source + tool's Type/Details). The kernel also
  // updates the in-memory state and emits oars:cleared for us.
  function _clearAgreementState() {
    if (eli.dashboard && typeof eli.dashboard.unpersistOars === "function") {
      return eli.dashboard.unpersistOars();
    }
    // Fallback for older kernels missing unpersistOars: remove what we can.
    try {
      var s = (Office && Office.context && Office.context.document && Office.context.document.settings);
      if (!s) return Promise.resolve(false);
      [SETTINGS_NAME, SETTINGS_TYPE, SETTINGS_DETAILS,
       "AgreementDataText", "AgreementDataSource"].forEach(function (k) {
        try { s.remove(k); } catch (e) {}
      });
      return new Promise(function (resolve) {
        s.saveAsync(function () { resolve(true); });
      });
    } catch (e) {
      eli.log.event("tool", "build_draft_clear_failed", { msg: e && e.message });
      return Promise.resolve(false);
    }
  }

  // FROM v2 showFileNameSettings → btnSaveActiveDoc (line 20852). Reads
  // body OOXML + per-section header/footer OOXML and bundles into a JSON
  // record for storage. Two short runRaw passes (body+sections, then
  // per-section HF) keep the budget tight on multi-section docs.
  function _captureActiveDocAsTemplate() {
    return eli.host.runRaw("build_draft:tpl_capture_body", function (context) {
      var doc = context.document;
      var bodyOoxml = doc.body.getOoxml();
      var sections = doc.sections;
      sections.load("items");
      return context.sync().then(function () {
        return { body: bodyOoxml.value, sectionCount: sections.items.length };
      });
    }).then(function (state) {
      // Per-section HF capture, one runRaw per section.
      var sectionsData = [];
      var chain = Promise.resolve();
      for (var i = 0; i < state.sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () {
            return eli.host.runRaw("build_draft:tpl_capture_section_" + idx, function (context) {
              var sections = context.document.sections;
              sections.load("items");
              return context.sync().then(function () {
                if (idx >= sections.items.length) return null;
                var sec = sections.items[idx];
                var grabs = {
                  primaryH: sec.getHeader("Primary").getOoxml(),
                  firstPageH: sec.getHeader("FirstPage").getOoxml(),
                  evenPagesH: sec.getHeader("EvenPages").getOoxml(),
                  primaryF: sec.getFooter("Primary").getOoxml(),
                  firstPageF: sec.getFooter("FirstPage").getOoxml(),
                  evenPagesF: sec.getFooter("EvenPages").getOoxml(),
                };
                return context.sync().then(function () {
                  return {
                    index: idx,
                    headers: {
                      primary: grabs.primaryH.value || "",
                      firstPage: grabs.firstPageH.value || "",
                      evenPages: grabs.evenPagesH.value || "",
                    },
                    footers: {
                      primary: grabs.primaryF.value || "",
                      firstPage: grabs.firstPageF.value || "",
                      evenPages: grabs.evenPagesF.value || "",
                    },
                  };
                });
              });
            }).then(function (data) { if (data) sectionsData.push(data); });
          });
        })(i);
      }
      return chain.then(function () {
        return { body: state.body, sections: sectionsData, savedDate: new Date().toISOString() };
      });
    });
  }

  // FROM v2 loadTemplateToWord (line 23762). Inserts a saved template
  // into the active doc. contentString is JSON ({body, sections}) for
  // full-fidelity OOXML templates, or plain text for legacy fallback.
  // Split into multiple short runRaw calls so each stays under 100ms:
  //   1.   Body OOXML insert
  //   2.   Per-section header/footer OOXML inserts (one runRaw per section)
  //   3a.  Body + tables font normalization
  //   3b.  Per-section H/F font normalization (one runRaw per section,
  //        all 3 HF types batched into 2 syncs vs 6)
  function _loadTemplateToWord(contentString) {
    var parsed = null;
    var isJson = false;
    try {
      if (String(contentString).trim().charAt(0) === "{") {
        parsed = JSON.parse(contentString);
        isJson = true;
      }
    } catch (e) { isJson = false; }

    showToast("📄 Inserting body…", "info");

    // Phase 1: insert OOXML or text. insertOoxml(replace) clears the
    // body for us — no body.clear() needed (saves one sync).
    return eli.host.runRaw("build_draft:tpl_body", function (context) {
      var body = context.document.body;
      if (isJson && parsed.body) {
        body.insertOoxml(parsed.body, Word.InsertLocation.replace);
      } else {
        body.insertText(String(contentString || ""), Word.InsertLocation.replace);
      }
      return context.sync();
    }).then(function () {
      // Phase 2: per-section header/footer insertion. Each section gets
      // its own runRaw to keep budgets tight on multi-section templates.
      if (!isJson || !parsed.sections || !parsed.sections.length) return null;
      showToast("📄 Headers & footers…", "info");
      var chain = Promise.resolve();
      parsed.sections.forEach(function (secData, idx) {
        chain = chain.then(function () {
          return eli.host.runRaw("build_draft:tpl_section_" + idx, function (context) {
            var sections = context.document.sections;
            sections.load("items");
            return context.sync().then(function () {
              if (idx >= sections.items.length) return;
              var sec = sections.items[idx];
              var hf = [
                { isHeader: true,  type: "Primary",   xml: secData.headers && secData.headers.primary },
                { isHeader: true,  type: "FirstPage", xml: secData.headers && secData.headers.firstPage },
                { isHeader: true,  type: "EvenPages", xml: secData.headers && secData.headers.evenPages },
                { isHeader: false, type: "Primary",   xml: secData.footers && secData.footers.primary },
                { isHeader: false, type: "FirstPage", xml: secData.footers && secData.footers.firstPage },
                { isHeader: false, type: "EvenPages", xml: secData.footers && secData.footers.evenPages },
              ];
              hf.forEach(function (h) {
                if (!h.xml) return;
                try {
                  var target = h.isHeader ? sec.getHeader(h.type) : sec.getFooter(h.type);
                  target.insertOoxml(h.xml, Word.InsertLocation.replace);
                } catch (e) {
                  eli.log.event("tool", "build_draft_tpl_hf_skip", { type: h.type, msg: e && e.message });
                }
              });
              return context.sync();
            });
          });
        });
      });
      return chain;
    }).then(function () {
      showToast("✨ Normalizing fonts…", "info");
      return _step3a_bodyFonts();
    }).then(function (sectionCount) {
      // Phase 3b: per-section H/F font normalization. One runRaw per
      // section so each stays under 100ms; within a runRaw all 3 HF
      // types are batched into 2 syncs (load all paragraphs → set fonts
      // + delete trailing empties → commit) instead of 6.
      if (!sectionCount) return null;
      var chain = Promise.resolve();
      for (var i = 0; i < sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () { return _step3b_sectionFonts(idx); });
        })(i);
      }
      return chain;
    }).then(function () {
      showToast("✅ Template loaded", "ok");
    });
  }

  // 3a. Body font + tables. One runRaw, 2 syncs. Returns section count
  // so the caller knows how many _step3b iterations to chain.
  function _step3a_bodyFonts() {
    return eli.host.runRaw("build_draft:tpl_fonts_body", function (context) {
      var body = context.document.body;
      body.font.name = "Times New Roman";
      body.font.size = 11;
      var tables = body.tables;
      tables.load("items");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        tables.items.forEach(function (table) {
          table.getRange().font.name = "Times New Roman";
        });
        return context.sync().then(function () { return sections.items.length; });
      });
    });
  }

  // 3b. One section's H/F font normalization. Batches all 3 HF types
  // (Primary/FirstPage/EvenPages) into 2 syncs total: one to load every
  // header + footer paragraph, one to commit font + trailing-empty
  // delete changes. Six round trips → two.
  function _step3b_sectionFonts(idx) {
    return eli.host.runRaw("build_draft:tpl_fonts_section_" + idx, function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        if (idx >= sections.items.length) return;
        var sec = sections.items[idx];
        var jobs = [];
        HF_TYPES.forEach(function (t) {
          try {
            var h = sec.getHeader(t);
            var f = sec.getFooter(t);
            h.paragraphs.load("items");
            f.paragraphs.load("items/text");
            jobs.push({ h: h, f: f, t: t });
          } catch (e) {
            eli.log.event("tool", "build_draft_tpl_font_load_skip", { type: t, msg: e && e.message });
          }
        });
        return context.sync().then(function () {
          jobs.forEach(function (j) {
            j.h.paragraphs.items.forEach(function (p) {
              p.font.name = "Times New Roman";
              p.font.size = 9;
            });
            for (var k = j.f.paragraphs.items.length - 1; k >= 0; k--) {
              var pp = j.f.paragraphs.items[k];
              var clean2 = pp.text.replace(/\s+/g, "").trim();
              pp.font.name = "Times New Roman";
              pp.font.size = 9;
              if (clean2.length === 0 && k > 0) {
                try { pp.delete(); }
                catch (e2) { eli.log.event("tool", "build_draft_tpl_footer_del_skip", { msg: e2 && e2.message }); }
              }
            }
          });
          return context.sync();
        });
      });
    });
  }

  function _findTemplateByType(detectedType) {
    if (!detectedType) return Promise.resolve(null);
    return eli.storage.getAll("bd_templates").then(function (rows) {
      if (!Array.isArray(rows) || !rows.length) return null;
      var lower = String(detectedType).toLowerCase();
      var match = rows.find(function (t) {
        return (t && t.agreementType && String(t.agreementType).toLowerCase() === lower)
            || (t && t.name && String(t.name).toLowerCase() === lower);
      });
      return match || null;
    }).catch(function () { return null; });
  }

  function _goHome() {
    if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
  }

  // === Step 1: logic generation ===
  // FROM v2 generateDocumentFromLogic (line 21595) + runSegmentedLogic
  // (line 21716). Split into 5 short runRaw phases so each stays under
  // the 100ms Word.run budget — phase boundaries make recovery clear,
  // unblock the UI thread between phases, and keep token counts low.
  // Phases:
  //   1a. Execute IF/ELSE plan (delete losing branches)
  //   1b. Replace {{key}} placeholders (one runRaw per key)
  //   1c. Delete DEF + TITLE scaffolding
  //   1d. {{DELETE_LINE}} → paragraph delete; {{ENTER}} → ZWSP
  //   1e. (deferred 300ms) collapse adjacent empty paragraphs
  function _runStep1Generation(answers) {
    showToast("⚙️ Generating document…", "info");
    return _step1a_executePlans(answers)
      .then(function () { return _step1b_replaceKeys(answers); })
      .then(function () { return _step1c_deleteScaffolds(); })
      .then(function () { return _step1d_specialTags(); })
      .then(function () { return _step1f_stripRemaining(); })
      .then(function () {
        // Background pass kicked off but not awaited — UX returns now.
        setTimeout(function () {
          _step1e_collapseEmpties().catch(function (e) {
            eli.log.event("tool", "build_draft_step1e_failed", { msg: e && e.message });
          });
        }, 300);
        showToast("✅ Step 1 complete → continuing to Step 2", "ok");
        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "build-draft", icon: "🏗️", label: "Build Draft",
            summary: Object.keys(answers).length + " field(s) populated",
            payload: { fieldCount: Object.keys(answers).length },
          });
        }
        setTimeout(function () { _runStep2(); }, 400);
      })
      .catch(function (err) {
        _wizardMode = false; // failed run shouldn't poison the next manual click
        eli.log.event("tool", "build_draft_step1_failed", { msg: err && err.message });
        showToast("Step 1 failed: " + (err && err.message), "err");
      });
  }

  // 1a. Execute IF/ELSE plans — collect tags, build plans, delete losing
  // branches. Single short pass over all tags; deepest-first sort so
  // nested deletions don't invalidate outer ranges.
  function _step1a_executePlans(answers) {
    return eli.host.runRaw("build_draft:step1a_plans", function (context) {
      var body = context.document.body;
      var tagSearch = body.search("\\{\\{[!\\}]@\\}\\}", { matchWildcards: true });
      tagSearch.load(["text", "index"]);
      return context.sync().then(function () {
        var tags = [];
        for (var i = 0; i < tagSearch.items.length; i++) {
          var rawTxt = tagSearch.items[i].text.replace(/[{}]/g, "").trim();
          if (rawTxt.indexOf("IF:") === 0 || rawTxt.indexOf("ELSEIF:") === 0
              || rawTxt.indexOf("ELSE") === 0 || rawTxt.indexOf("ENDIF") === 0) {
            tags.push({ range: tagSearch.items[i], text: rawTxt, index: i });
          }
        }
        var blockStack = [];
        var executionPlans = [];
        for (var j = 0; j < tags.length; j++) {
          var t = tags[j];
          var txt = t.text;
          if (txt.indexOf("IF:") === 0) {
            var blk = { segments: [], startTagIndex: j, depth: blockStack.length };
            blk.segments.push({ condition: txt.substring(3).trim(), tagIndex: j });
            blockStack.push(blk);
          } else if (txt.indexOf("ELSEIF:") === 0) {
            var blk2 = blockStack.length ? blockStack[blockStack.length - 1] : null;
            if (blk2) {
              blk2.segments[blk2.segments.length - 1].endTagIndex = j;
              blk2.segments.push({ condition: txt.substring(7).trim(), tagIndex: j });
            }
          } else if (txt.indexOf("ELSE") === 0) {
            var blk3 = blockStack.length ? blockStack[blockStack.length - 1] : null;
            if (blk3) {
              blk3.segments[blk3.segments.length - 1].endTagIndex = j;
              blk3.segments.push({ condition: "true", tagIndex: j });
            }
          } else if (txt.indexOf("ENDIF") === 0) {
            var done = blockStack.pop();
            if (done) {
              done.segments[done.segments.length - 1].endTagIndex = j;
              executionPlans.push({ segments: done.segments, finalEndTagIndex: j, depth: done.depth });
            }
          }
        }
        executionPlans.sort(function (a, b) { return b.depth - a.depth; });
        for (var p = 0; p < executionPlans.length; p++) {
          var plan = executionPlans[p];
          var winning = -1;
          for (var s = 0; s < plan.segments.length; s++) {
            if (evalLogicCondition(plan.segments[s].condition, answers)) { winning = s; break; }
          }
          if (winning > -1) {
            for (var s2 = 0; s2 < plan.segments.length; s2++) {
              var seg = plan.segments[s2];
              var startTag = tags[seg.tagIndex].range;
              if (seg.endTagIndex === undefined) continue;
              var endTag = tags[seg.endTagIndex].range;
              if (s2 === winning) {
                startTag.delete();
              } else {
                var rng = startTag.getRange("Start").expandTo(endTag.getRange("Start"));
                rng.delete();
              }
            }
            if (tags[plan.finalEndTagIndex]) tags[plan.finalEndTagIndex].range.delete();
          } else if (plan.segments.length && plan.finalEndTagIndex !== undefined) {
            var firstTag = tags[plan.segments[0].tagIndex].range;
            var finalTag = tags[plan.finalEndTagIndex].range;
            var del = firstTag.getRange("Start").expandTo(finalTag.getRange("End"));
            del.delete();
          }
        }
        return context.sync();
      });
    });
  }

  // 1b. Replace each {{key}} / {{key:formatter}} with the answer. One
  // runRaw per key keeps each pass tiny and lets the UI breathe.
  function _step1b_replaceKeys(answers) {
    var keys = Object.keys(answers);
    var chain = Promise.resolve();
    keys.forEach(function (key) {
      chain = chain.then(function () {
        return eli.host.runRaw("build_draft:step1b_key", function (context) {
          var body = context.document.body;
          var pattern = "\\{\\{" + key + "*\\}\\}";
          var res = body.search(pattern, { matchWildcards: true });
          res.load("text");
          return context.sync().then(function () {
            for (var i = res.items.length - 1; i >= 0; i--) {
              var item = res.items[i];
              var tagContent = item.text.replace(/^\{\{|\}\}$/g, "").trim();
              var pair = tagContent.split(":");
              var tagKey = pair[0].trim();
              var fmt = pair.length > 1 ? pair[1].trim().toUpperCase() : null;
              if (tagKey !== key) continue;
              var finalVal = answers[key];
              if (fmt === "UPPER") finalVal = String(finalVal).toUpperCase();
              else if (fmt === "LOWER") finalVal = String(finalVal).toLowerCase();
              else if (fmt === "TITLE") {
                finalVal = String(finalVal).replace(/\w\S*/g, function (w) {
                  return w.charAt(0).toUpperCase() + w.substr(1).toLowerCase();
                });
              }
              var clean = String(finalVal).trim().toLowerCase().replace(/['"’]/g, "");
              var isOther = clean === "other";
              var isUnknown = clean.indexOf("dont know") !== -1 || clean.indexOf("don't know") !== -1;
              if (isOther) finalVal = "[" + finalVal + "]";
              else if (isUnknown) finalVal = "[THIRD PARTY TO FILL IN - " + key.toUpperCase() + "]";
              var inserted = item.insertText(finalVal, "Replace");
              if (isOther || isUnknown) {
                inserted.font.color = "#c62828";
                inserted.font.bold = true;
              }
            }
            return context.sync();
          });
        });
      });
    });
    return chain;
  }

  // 1c. Delete DEF + TITLE scaffolding tags (no longer needed once
  // the visible content has been resolved).
  function _step1c_deleteScaffolds() {
    return eli.host.runRaw("build_draft:step1c_scaffolds", function (context) {
      var body = context.document.body;
      var defs = body.search("\\{\\{DEF:*\\}\\}", { matchWildcards: true });
      var titles = body.search("\\{\\{TITLE:*\\}\\}", { matchWildcards: true });
      defs.load("items");
      titles.load("items");
      return context.sync().then(function () {
        for (var i = defs.items.length - 1; i >= 0; i--) defs.items[i].delete();
        for (var k = titles.items.length - 1; k >= 0; k--) titles.items[k].delete();
        return context.sync();
      });
    });
  }

  // 1d. {{DELETE_LINE}} → drop paragraph; {{ENTER}} → zero-width space.
  function _step1d_specialTags() {
    return eli.host.runRaw("build_draft:step1d_special", function (context) {
      var body = context.document.body;
      var del = body.search("\\{\\{DELETE_LINE\\}\\}", { matchWildcards: true });
      var ent = body.search("\\{\\{ENTER\\}\\}", { matchWildcards: true });
      del.load("items");
      ent.load("items");
      return context.sync().then(function () {
        for (var i = del.items.length - 1; i >= 0; i--) {
          try { del.items[i].paragraphs.getFirst().delete(); }
          catch (e) { eli.log.event("tool", "build_draft_delete_line_skip", { msg: e && e.message }); }
        }
        for (var k = ent.items.length - 1; k >= 0; k--) {
          ent.items[k].insertText("​", "Replace");
        }
        return context.sync();
      });
    });
  }

  // 1f. Final tidy: strip ANY surviving {{...}} tags. Catches keys with
  // no answer (user removed input), malformed tags, etc. Runs after the
  // main chain so the wizard advances even if the doc had stragglers.
  function _step1f_stripRemaining() {
    return eli.host.runRaw("build_draft:step1f_strip", function (context) {
      var body = context.document.body;
      var leftovers = body.search("\\{\\{*\\}\\}", { matchWildcards: true });
      leftovers.load("text");
      return context.sync().then(function () {
        for (var i = leftovers.items.length - 1; i >= 0; i--) {
          try { leftovers.items[i].delete(); }
          catch (e) { eli.log.event("tool", "build_draft_strip_skip", { msg: e && e.message }); }
        }
        return context.sync();
      });
    });
  }

  // 1e. Collapse adjacent empty paragraphs. Background pass — not
  // awaited by main flow.
  function _step1e_collapseEmpties() {
    return eli.host.runRaw("build_draft:step1e_collapse", function (context) {
      var paras = context.document.body.paragraphs;
      paras.load("items/text");
      return context.sync().then(function () {
        for (var i = paras.items.length - 1; i > 0; i--) {
          var curr = paras.items[i];
          var above = paras.items[i - 1];
          if (curr.text.trim().length === 0
              && curr.text.indexOf("​") === -1
              && curr.text.indexOf("\f") === -1
              && above.text.trim().length === 0) {
            try { curr.delete(); }
            catch (e) { eli.log.event("tool", "build_draft_collapse_skip", { msg: e && e.message }); }
          }
        }
        return context.sync();
      });
    });
  }

  // === Step 2: template fill ===
  // Scan body+headers+footers, detect placeholders, route to
  // showStep1Reminder if {{ still present, else render fill form.
  function _runStep2() {
    showToast("🔍 Scanning placeholders…", "info");
    return eli.events.safeAsync(_scanForFill(), "build_draft.fill_scan")
      .then(function (text) {
        if (text.indexOf("{{") !== -1 || text.indexOf("}}") !== -1) {
          _showStep1Reminder(function () { _showStep2Form(text, true); });
          return;
        }
        _showStep2Form(text, false);
      })
      .catch(function (err) {
        eli.log.event("tool", "build_draft_step2_scan_failed", { msg: err && err.message });
        showToast("Step 2 scan failed: " + (err && err.message), "err");
      });
  }

  function _showStep1Reminder(onIgnore) {
    if (typeof showEliDialog !== "function") { onIgnore && onIgnore(); return; }
    showEliDialog({
      variant: "warning",
      icon: "🚧",
      title: "Unprocessed Logic Detected",
      paragraphs: [
        "I found <b>{{Curly Braces}}</b> in this document.",
        "Did you remember to run <b>Step 1 (Build Logic)</b> to process the IF/ELSE rules first?",
      ],
      primary: { label: "🔙 Go to Step 1", onClick: function () {
        var mount = document.getElementById("_eli3_dashboard_root");
        if (mount) _show({});
        setTimeout(function () { _renderLogicPanel(); }, 50);
      } },
      secondary: { label: "⏩ Ignore & Continue", onClick: function () {
        if (onIgnore) onIgnore();
      } },
    });
  }

  function _showStep2Form(scannedText, forced) {
    var placeholders = extractTemplatePlaceholders(scannedText);
    var mount = document.getElementById("_eli3_dashboard_root");
    var sourceText = (_footerFile && _footerFile.text) || "";
    var sourceName = (_footerFile && _footerFile.name) || null;
    renderTemplateFillForm({
      mount: mount,
      placeholders: placeholders,
      sourceText: sourceText,
      sourceName: sourceName,
      onBack: function () { _show({}); },
      onLocate: eli.events.guard(function (placeholder, val) {
        var needle = placeholder;
        eli.events.safeAsync(eli.host.runRaw("build_draft:fill_locate", function (context) {
          var body = context.document.body;
          var found = body.search(needle, { matchCase: false, ignoreSpace: true });
          found.load("items");
          return context.sync().then(function () {
            if (found.items.length) {
              found.items[0].select();
              return context.sync();
            } else if (val && val.length > 1) {
              var v = body.search(val, { matchCase: false, ignoreSpace: true });
              v.load("items");
              return context.sync().then(function () {
                if (v.items.length) { v.items[0].select(); return context.sync(); }
              });
            }
          });
        }), "build_draft.fill_locate");
      }, "build_draft.fill_locate"),
      onAutoFill: eli.events.guard(function (phs, cb) {
        _aiFillPlaceholders(phs, sourceText, cb);
      }, "build_draft.autofill"),
      onUpload: eli.events.guard(function (file, phs, cb) {
        _readFileForFill(file, function (text, err) {
          if (err) { cb(null, err); return; }
          _aiFillPlaceholders(phs, text, cb);
        });
      }, "build_draft.fill_upload"),
      onApply: eli.events.guard(function (values) {
        _runStep2Apply(values);
      }, "build_draft.fill_apply"),
    });
  }

  // Read .docx (mammoth), .pdf (base64 inline-data for Gemini), or
  // plain text from a File object. PDFs callback with a sentinel object
  // so the AI fill path can route inlineData through to eli.ai.
  function _readFileForFill(file, cb) {
    var ext = String(file.name || "").split(".").pop().toLowerCase();
    var reader = new FileReader();
    if (ext === "docx" && window.mammoth && window.mammoth.extractRawText) {
      reader.onload = function () {
        window.mammoth.extractRawText({ arrayBuffer: reader.result })
          .then(function (r) { cb((r && r.value) || "", null); })
          .catch(function (err) { cb(null, err || new Error("docx parse failed")); });
      };
      reader.onerror = function () { cb(null, new Error("File read failed")); };
      reader.readAsArrayBuffer(file);
    } else if (ext === "pdf") {
      // Stash the base64 in _footerFile so _aiFillPlaceholders picks it
      // up via aiOpts.inlineData (matches v2 AGREEMENT_DATA shape).
      reader.onload = function () {
        var dataUrl = String(reader.result || "");
        var commaIdx = dataUrl.indexOf(",");
        var base64 = commaIdx === -1 ? dataUrl : dataUrl.substring(commaIdx + 1);
        _footerFile = {
          name: file.name, size: file.size, text: "[PDF: " + file.name + "]",
          isBase64: true, mime: "application/pdf", data: base64,
        };
        cb("[PDF: " + file.name + "]", null);
      };
      reader.onerror = function () { cb(null, new Error("PDF read failed")); };
      reader.readAsDataURL(file);
    } else {
      reader.onload = function () { cb(String(reader.result || ""), null); };
      reader.onerror = function () { cb(null, new Error("File read failed")); };
      reader.readAsText(file);
    }
  }

  // AI auto-fill: load templateMap prompt, format with placeholders +
  // file content, call eli.ai.completeJSON. FROM v2 templateMap usage.
  // Caches by (sourceText, placeholder-set) hash so re-clicks are free.
  function _aiFillPlaceholders(placeholders, sourceText, cb) {
    if (!sourceText) { cb(null, new Error("No data source to map from")); return; }
    if (!placeholders.length) { cb({}, null); return; }
    var cleanKeys = placeholders.map(function (ph) {
      var raw = ph.replace(/[\[\]{}]/g, "").replace(/^(\$!|\$|!)/, "");
      if (raw.indexOf("||") !== -1) {
        var parts = raw.split("||");
        return { display: ph, ai: parts[0].trim() };
      }
      return { display: ph, ai: raw };
    });
    var cacheKey = sourceText + "|" + cleanKeys.map(function (k) { return k.ai; }).sort().join(",");
    function _mergeAndDeliver(mapping) {
      var merged = {};
      cleanKeys.forEach(function (k) {
        if (mapping[k.ai] !== undefined) {
          merged[k.display] = mapping[k.ai];
          merged[k.ai] = mapping[k.ai];
        } else if (mapping[k.display] !== undefined) {
          merged[k.display] = mapping[k.display];
        }
      });
      cb(merged, null);
    }
    // Cache hit?
    _bd_aiCacheGet(cacheKey).then(function (cached) {
      if (cached) {
        eli.log.event("tool", "build_draft_ai_fill_cache_hit", {});
        _mergeAndDeliver(cached);
        return;
      }
      eli.events.safeAsync(eli.storage.get("prompts", "templateMap"), "build_draft.prompt_load")
        .then(function (row) {
          if (!row || !row.text) { cb(null, new Error("templateMap prompt missing")); return; }
          var prompt = eli.ai.formatPrompt(row.text, {
            placeholders: cleanKeys.map(function (k) { return k.ai; }).join("\n"),
            fileContent: sourceText,
          });
          // PDF base64 path: pass binary as inline-data part for Gemini.
          var aiOpts = { maxTokens: 4000 };
          if (_footerFile && _footerFile.isBase64 && _footerFile.mime && _footerFile.data) {
            aiOpts.inlineData = [{ mimeType: _footerFile.mime, data: _footerFile.data }];
          }
          eli.events.safeAsync(eli.ai.completeJSON(prompt, null, aiOpts), "build_draft.ai_fill")
            .then(function (mapping) {
              if (mapping && typeof mapping === "object") _bd_aiCachePut(cacheKey, mapping);
              _mergeAndDeliver(mapping);
            })
            .catch(function (err) { cb(null, err || new Error("AI fill failed")); });
        })
        .catch(function (err) { cb(null, err || new Error("Prompt load failed")); });
    });
  }

  // FROM v2 applyTemplateValues runBatch (line 6854) + cleanupSpecificTags
  // (line 6906). Searches each placeholder across body + every header/footer
  // and replaces with the user's value; deletes leftover $! payment-trigger
  // tags after successful fill.
  function _runStep2Apply(values) {
    var keys = Object.keys(values).filter(function (k) { return values[k] && String(values[k]).trim(); });
    if (!keys.length) { showToast("No values to apply.", "warn"); return; }
    // Sort longest-first so e.g. "[[Client Name]]" matches before "[[Client]]".
    keys.sort(function (a, b) { return b.length - a.length; });
    showToast("⚙️ Applying " + keys.length + " field(s)…", "info");
    var tagsToKill = []; // $![ payment-trigger tags get fully deleted after.
    var totalCount = 0;
    var batches = [];
    for (var bi = 0; bi < keys.length; bi += STEP2_APPLY_BATCH) {
      batches.push(keys.slice(bi, bi + STEP2_APPLY_BATCH));
    }
    var batchChain = Promise.resolve();
    batches.forEach(function (batch) {
      batchChain = batchChain.then(function () {
        return _step2_applyBatch(batch, values, tagsToKill).then(function (n) { totalCount += n; });
      });
    });
    return batchChain
      .then(function () {
        if (!tagsToKill.length) return;
        return _step2_cleanupTags(tagsToKill).catch(function (e) {
          eli.log.event("tool", "build_draft_step2_cleanup_failed", { msg: e && e.message });
        });
      })
      .then(function () {
        showToast("✅ Applied " + totalCount + " replacement(s)", "ok");
        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "build-draft", icon: "📝", label: "Build Draft · Fill",
            summary: totalCount + " replacement(s) applied",
            payload: { count: totalCount },
          });
        }
        // Mirrors v2 finishUp → runPreSaveScan: scan for residual [bracket]
        // markers before advancing to Step 3.
        return _runPreSaveScan();
      })
      .catch(function (err) {
        _wizardMode = false;
        eli.log.event("tool", "build_draft_step2_apply_failed", { msg: err && err.message });
        showToast("Apply failed: " + (err && err.message), "err");
      });
  }

  // FROM v2 runPreSaveScan (line 22657). Searches for residual [...] bracket
  // markers that aren't red (red = "other"/"don't know" placeholders user
  // chose to leave). If any survive, opens the bracket cleaner; else
  // auto-advances per wizard mode.
  function _runPreSaveScan() {
    return eli.host.runRaw("build_draft:pre_save_scan", function (context) {
      var results = context.document.body.search("\\[[!]]@\\]", { matchWildcards: true });
      results.load("items");
      return context.sync().then(function () {
        for (var i = 0; i < results.items.length; i++) {
          results.items[i].font.load("color");
          results.items[i].load("text");
        }
        return context.sync().then(function () {
          var bracketsFound = [];
          results.items.forEach(function (item) {
            var color = (item.font.color || "").toLowerCase();
            var isRed = color === "#c62828" || color === "red" || color === "#ff0000";
            if (!isRed) {
              var text = item.text;
              if (text.indexOf("[[") === 0 && text.lastIndexOf("]]") !== text.length - 2) text = text + "]";
              bracketsFound.push({ text: text, inner: text.replace(/^\[+|\]+$/g, "") });
            }
          });
          return bracketsFound;
        });
      });
    }).then(function (items) {
      if (items.length) {
        showToast("🧹 " + items.length + " placeholder(s) need review.", "warn");
        _showPreSaveCleaner(items);
        return;
      }
      if (_wizardMode) {
        showToast("🚀 Clean. Proceeding to Step 3…", "ok");
        setTimeout(function () { _runStep3ErrorReview(); }, 600);
      } else {
        showToast("✅ Clean & Verified", "ok");
        setTimeout(function () { _show({}); }, 600);
      }
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_presave_failed", { msg: err && err.message });
      // Fall through to hub on scan failure — user can retry.
      _show({});
    });
  }

  // Mounts the bracket cleaner panel on the pre-save items. onDone wires
  // back into the wizard chain (advance to Step 3) or the hub.
  function _showPreSaveCleaner(items) {
    if (!renderBracketCleaner) { _show({}); return; }
    var mount = document.getElementById("_eli3_dashboard_root");
    eli.events.safeAsync(eli.storage.getAll("cleaner_rules"), "build_draft.cleaner_rules")
      .then(function (rules) {
        renderBracketCleaner({
          mount: mount,
          brackets: { items: items },
          financial: { items: [] },
          cleanerRules: rules || [],
          onBack: function () { _show({}); },
          onDone: function () {
            if (_wizardMode) {
              showToast("🚀 Proceeding to Step 3…", "ok");
              setTimeout(function () { _runStep3ErrorReview(); }, 400);
            } else {
              _show({});
            }
          },
          onLocate: eli.events.guard(function (row) {
            eli.events.safeAsync(
              eli.host.runRaw("build_draft:locate", function (context) {
                var body = context.document.body;
                var found = body.search(row.text, { matchCase: false, matchWholeWord: false });
                found.load("items");
                return context.sync().then(function () {
                  if (found.items.length) { found.items[0].select(); return context.sync(); }
                });
              }),
              "build_draft.locate"
            );
          }, "build_draft.locate"),
          onSowHelper: eli.events.guard(function (row) {
            if (!row.rule || !renderSowHelper) return;
            renderSowHelper({
              rule: row.rule,
              target: row.text,
              onPick: eli.events.guard(function (picked) {
                eli.events.safeAsync(
                  eli.host.runRaw("build_draft:replace", function (context) {
                    var body = context.document.body;
                    var found = body.search(row.text, { matchCase: false, matchWholeWord: false });
                    found.load("items");
                    return context.sync().then(function () {
                      if (found.items.length) {
                        found.items[0].insertText(picked.text, "Replace");
                        return context.sync();
                      }
                    });
                  }),
                  "build_draft.replace"
                ).then(function () { showToast("✅ Inserted: " + picked.label, "ok"); });
              }, "build_draft.sow.pick"),
            });
          }, "build_draft.sow"),
        });
      });
  }

  // One batch = up to STEP2_APPLY_BATCH keys × (body + per-section
  // headers/footers). Returns the count of replacements made.
  function _step2_applyBatch(batch, values, tagsToKill) {
    return eli.host.runRaw("build_draft:step2_apply_batch", function (context) {
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        var count = 0;
        var chain = Promise.resolve();
        batch.forEach(function (key) {
          chain = chain.then(function () {
            var rawVal = String(values[key]);
            var isPaymentTrigger = key.indexOf("$![") === 0;
            var isCurrency = isPaymentTrigger || key.indexOf("$[") === 0;
            var finalVal = rawVal;
            if (isCurrency && finalVal.trim().charAt(0) !== "$") finalVal = "$" + finalVal;
            // Word treats "\v" (vertical tab) as a soft line break.
            var insertVal = finalVal.replace(/\n/g, "");
            if (isPaymentTrigger) tagsToKill.push(key);
            var searchOpts = { matchCase: false, ignoreSpace: true, ignorePunctuation: false };
            // Body
            var bodyRes = context.document.body.search(key, searchOpts);
            bodyRes.load("items");
            return context.sync().then(function () {
              for (var k = 0; k < bodyRes.items.length; k++) {
                bodyRes.items[k].insertText(insertVal, "Replace");
                count++;
              }
              // Headers + footers across all sections.
              var hfChain = Promise.resolve();
              for (var s = 0; s < sections.items.length; s++) {
                (function (sec) {
                  HF_TYPES.forEach(function (t) {
                    hfChain = hfChain.then(function () {
                      var ranges = [];
                      try { ranges.push(sec.getHeader(t)); }
                      catch (e) { eli.log.event("tool", "build_draft_apply_header_skip", { msg: e && e.message }); }
                      try { ranges.push(sec.getFooter(t)); }
                      catch (e) { eli.log.event("tool", "build_draft_apply_footer_skip", { msg: e && e.message }); }
                      var subChain = Promise.resolve();
                      ranges.forEach(function (r) {
                        subChain = subChain.then(function () {
                          var rr = r.search(key, searchOpts);
                          rr.load("items");
                          return context.sync().then(function () {
                            for (var h = 0; h < rr.items.length; h++) {
                              rr.items[h].insertText(insertVal, "Replace");
                              count++;
                            }
                          });
                        });
                      });
                      return subChain;
                    });
                  });
                })(sections.items[s]);
              }
              return hfChain;
            });
          });
        });
        return chain.then(function () { return count; });
      });
    });
  }

  // Cleanup pass for $![...] payment-trigger tags. Body-only (these
  // never live in headers/footers).
  function _step2_cleanupTags(tagsToKill) {
    return eli.host.runRaw("build_draft:step2_cleanup", function (context) {
      var body = context.document.body;
      var uniq = tagsToKill.filter(function (v, i, a) { return a.indexOf(v) === i; });
      var chain = Promise.resolve();
      uniq.forEach(function (tag) {
        chain = chain.then(function () {
          var r = body.search(tag, { matchCase: false, matchWildcards: false });
          r.load("items");
          return context.sync().then(function () {
            for (var k = r.items.length - 1; k >= 0; k--) {
              try { r.items[k].delete(); }
              catch (e) { eli.log.event("tool", "build_draft_cleanup_delete_skip", { msg: e && e.message }); }
            }
          });
        });
      });
      return chain;
    });
  }

