  // FROM v2 showFileNameSettings (line 20740). Templates view: file-name
  // pattern config + per-agreement-type template library + active-doc
  // capture + bulk import/export.
  function _renderTemplatesPanel() {
    if (!renderTemplatesView) {
      // Fallback to v2 global if the view fn isn't bundled yet.
      if (typeof window.showFileNameSettings === "function") {
        try { window.showFileNameSettings(); return; }
        catch (e) { showToast("Templates view failed: " + (e && e.message), "err"); return; }
      }
      showToast("Templates view not loaded.", "warn");
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    eli.events.safeAsync(eli.storage.getAll("bd_templates"), "build_draft.tpl_list").then(function (templates) {
      // User-pattern + highlight settings live in v2's userSettings via
      // localStorage; read through eli.compat.lsGet to honor v2 keys.
      var rawSettings = null;
      try { rawSettings = eli.compat.lsGet("eli_user_settings"); } catch (e) {}
      var settings = {};
      try { settings = rawSettings ? JSON.parse(rawSettings) : {}; } catch (e) {}
      var patterns = settings.fileNamePatterns || {
        colgate: "[Ref] - CP-[Party] -- [Type] (DRAFT [Date])",
        hills: "[Ref] - HPN-[Party] -- [Type] (DRAFT [Date])",
      };
      renderTemplatesView({
        mount: mount,
        templates: templates || [],
        patterns: patterns,
        highlightFill: !!settings.highlightFill,
        onBack: function () { _show({}); },
        onSavePatterns: eli.events.guard(function (payload) {
          settings.fileNamePatterns = payload.patterns;
          settings.highlightFill = payload.highlightFill;
          try {
            eli.compat.lsSet("eli_user_settings", JSON.stringify(settings));
            showToast("✅ Patterns saved", "ok");
          } catch (e) {
            eli.log.event("tool", "build_draft_settings_save_failed", { msg: e && e.message });
            showToast("Save failed: " + (e && e.message), "err");
          }
        }, "build_draft.tpl_save_patterns"),
        onSaveActiveDoc: eli.events.guard(function (payload) {
          showToast("⏳ Capturing active document…", "info");
          _captureActiveDocAsTemplate().then(function (captured) {
            var displayName = payload.type + (payload.party ? " - " + payload.party : "");
            var rec = {
              id: "bd_doc_" + Date.now(),
              name: displayName,
              type: payload.category, // "MasterXML" | "PriorAgreement"
              agreementType: payload.type.toLowerCase(),
              party: payload.party || "",
              content: JSON.stringify({
                agreementType: payload.type,
                partyName: payload.party || "",
                savedDate: captured.savedDate,
                body: captured.body,
                sections: captured.sections,
              }),
              savedDate: new Date().toLocaleString(),
              timestamp: Date.now(),
            };
            // De-dup: same agreementType + type + party gets replaced.
            return eli.storage.getAll("bd_templates").then(function (existing) {
              var list = (existing || []).filter(function (x) {
                return !(x.agreementType === rec.agreementType && x.type === rec.type && x.party === rec.party);
              });
              list.push(rec);
              // bd_templates is keyed by id; put each row.
              return eli.storage.put("bd_templates", rec);
            }).then(function () {
              showToast("✅ Template Saved", "ok");
              _renderTemplatesPanel(); // refresh
            });
          }).catch(function (err) {
            eli.log.event("tool", "build_draft_tpl_capture_failed", { msg: err && err.message });
            showToast("Capture failed: " + (err && err.message), "err");
            _renderTemplatesPanel();
          });
        }, "build_draft.tpl_save_active"),
        onLoadTemplate: eli.events.guard(function (tpl) {
          if (!tpl || !tpl.content) { showToast("Template has no content.", "err"); return; }
          showToast("⏳ Loading " + (tpl.name || "template") + "…", "info");
          _loadTemplateToWord(tpl.content)
            .then(function () { showToast("✅ Template loaded", "ok"); })
            .catch(function (err) {
              eli.log.event("tool", "build_draft_tpl_load_failed", { msg: err && err.message });
              showToast("Load failed: " + (err && err.message), "err");
            });
        }, "build_draft.tpl_load"),
        onDeleteTemplate: eli.events.guard(function (tpl) {
          eli.events.safeAsync(eli.ui.confirm({
            title: "Delete template?",
            message: "Delete '" + (tpl.name || "this template") + "'? This cannot be undone.",
          }), "build_draft.tpl_delete_confirm").then(function (ok) {
            if (!ok) return;
            return eli.storage.delete("bd_templates", tpl.id).then(function () {
              showToast("🗑️ Deleted: " + (tpl.name || tpl.id), "ok");
              _renderTemplatesPanel();
            });
          }).catch(function (err) {
            eli.log.event("tool", "build_draft_tpl_delete_failed", { msg: err && err.message });
          });
        }, "build_draft.tpl_delete"),
        onBulkImport: eli.events.guard(function (file) {
          var reader = new FileReader();
          reader.onload = function () {
            var imported;
            try { imported = JSON.parse(reader.result); }
            catch (e) { showToast("Invalid JSON file", "err"); return; }
            if (!Array.isArray(imported)) { showToast("Expected an array", "err"); return; }
            // Merge by (agreementType, type, party) key.
            eli.storage.getAll("bd_templates").then(function (current) {
              var dbMap = {};
              (current || []).forEach(function (item) {
                var k = (item.agreementType || "") + "::" + (item.type || "") + "::" + (item.party || "").toLowerCase();
                dbMap[k] = item;
              });
              var countNew = 0, countUpd = 0;
              imported.forEach(function (newItem) {
                var k = (newItem.agreementType || "").toLowerCase() + "::" + (newItem.type || "") + "::" + (newItem.party || "").toLowerCase();
                if (dbMap[k]) { newItem.id = newItem.id || dbMap[k].id; countUpd++; }
                else { newItem.id = newItem.id || "bd_imp_" + Date.now() + "_" + Math.random().toString(36).slice(2); countNew++; }
                dbMap[k] = newItem;
              });
              var chain = Promise.resolve();
              Object.keys(dbMap).forEach(function (k) {
                chain = chain.then(function () { return eli.storage.put("bd_templates", dbMap[k]); });
              });
              return chain.then(function () {
                showToast("✅ Import: " + countNew + " new, " + countUpd + " updated", "ok");
                _renderTemplatesPanel();
              });
            });
          };
          reader.readAsText(file);
        }, "build_draft.tpl_import"),
      });
    });
  }

  // Step 3 — Error Review. Dispatches to the error_review tool's tile
  // dispatch channel (registered by the error_review bundle); falls back
  // to the v2 global if v3 hasn't loaded the tool yet. Wizard mode ends
  // here — error_review and showSaveAsManager are end-points, not auto-
  // advancing.
  function _runStep3ErrorReview() {
    _wizardMode = false; // wizard chain ends; user owns the flow now
    var dispatched = false;
    try {
      if (eli.dispatch) {
        var result = eli.dispatch("tile", "app_error_review");
        if (result !== undefined) dispatched = true;
      }
    } catch (e) {
      eli.log.event("tool", "build_draft_step3_dispatch_failed", { msg: e && e.message });
    }
    if (dispatched) return;
    if (typeof window.runInteractiveErrorCheck === "function") {
      try { window.runInteractiveErrorCheck(function () { _show({}); }); }
      catch (e) { showToast("Error Review failed: " + (e && e.message), "err"); }
      return;
    }
    showToast("Error Review tool not installed.", "warn");
  }

  // Step 4 — Save and/or Send. FROM v2 showSaveAsManager (line 18930).
  // Renders prefill form, scans doc with AI in background to fill third-
  // party / ref / type, then saves the .docx via Office.context.document.
  // Falls back to v2 global if the v3 render fn isn't bundled yet.
  function _runStep4SaveSend() {
    if (!renderSavePanel) {
      if (typeof window.showSaveAsManager === "function") {
        try { window.showSaveAsManager(); return; }
        catch (e) { showToast("Save manager failed: " + (e && e.message), "err"); return; }
      }
      showToast("Save / Send not yet migrated to v3.", "warn");
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");

    // Read v2 user-settings for filename patterns.
    var settings = {};
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      if (raw) settings = JSON.parse(raw) || {};
    } catch (e) {}
    var patterns = settings.fileNamePatterns || null;

    // Pull agreement-type list from IDB (data bundle).
    eli.events.safeAsync(eli.storage.getAll("agreementTypes"), "build_draft.ag_types").then(function (rows) {
      var agTypes = [];
      if (Array.isArray(rows)) {
        agTypes = rows.map(function (r) { return r && (r.label || r.name || r.id); }).filter(Boolean);
      }
      // Render with scanning=true; AI prefill flows in async.
      _renderSavePanelWith({ prefill: {}, agTypes: agTypes, patterns: patterns, scanning: true, mount: mount });
      // Kick off prefill scan; re-render on completion with prefill data.
      _runSavePrefillScan().then(function (prefill) {
        _renderSavePanelWith({ prefill: prefill || {}, agTypes: agTypes, patterns: patterns, scanning: false, mount: mount });
      }).catch(function (err) {
        eli.log.event("tool", "build_draft_save_prefill_failed", { msg: err && err.message });
        _renderSavePanelWith({ prefill: {}, agTypes: agTypes, patterns: patterns, scanning: false, mount: mount });
      });
    });
  }

  function _renderSavePanelWith(state) {
    renderSavePanel({
      mount: state.mount,
      prefill: state.prefill,
      agTypes: state.agTypes,
      patterns: state.patterns,
      scanning: state.scanning,
      onBack: function () { _show({}); },
      onSettings: function () { _renderTemplatesPanel(); },
      onSkip: function () {
        showToast("⏩ Done (no save)", "info");
        _show({});
      },
      onSave: eli.events.guard(function (formData) {
        _runSaveAsDocx(formData);
      }, "build_draft.save"),
    });
  }

  // Lightweight AI prefill scan: pulls entity / type / party / ref from
  // the active document. Uses cached extraction when available.
  function _runSavePrefillScan() {
    return eli.host.runRaw("build_draft:save_scan", function (context) {
      var body = context.document.body;
      body.load("text");
      return context.sync().then(function () {
        // Cap text — entity/party are usually in the first ~5K chars.
        return String(body.text || "").substring(0, 8000);
      });
    }).then(function (docText) {
      if (!docText) return null;
      // Cache hit via per-doc hash.
      return _bd_aiCacheGet("save_prefill:" + docText).then(function (cached) {
        if (cached) {
          eli.log.event("tool", "build_draft_save_prefill_cache_hit", {});
          return cached;
        }
        var prompt =
          "From the contract excerpt below, extract: (1) which Colgate entity is the contracting party (Colgate or Hills); (2) the third-party / counterparty name; (3) the agreement type (NDA, MSA, etc.); (4) any CP reference number.\n" +
          "Return raw JSON: {\"entity\":\"Colgate|Hills\",\"third_party_entity\":\"...\",\"type\":\"...\",\"cp_ref\":\"...\"}\n" +
          "Use empty string for any field not found.\n\n" +
          "--- DOCUMENT ---\n" + docText;
        return eli.events.safeAsync(eli.ai.completeJSON(prompt, null, { maxTokens: 1000 }), "build_draft.save_prefill")
          .then(function (json) {
            if (json && typeof json === "object") {
              _bd_aiCachePut("save_prefill:" + docText, json);
              return json;
            }
            return null;
          });
      });
    });
  }

  // FROM v2 saveFileWithDialog (line 19174). Pulls the doc via
  // Office.context.document.getFileAsync (slice loop) then writes via
  // showSaveFilePicker (modern browsers) or anchor-download fallback.
  function _runSaveAsDocx(formData) {
    showToast("⏳ Generating .docx…", "info");
    return new Promise(function (resolve, reject) {
      try {
        Office.context.document.getFileAsync(Office.FileType.Compressed, { sliceSize: 65536 }, function (result) {
          if (result.status !== Office.AsyncResultStatus.Succeeded) {
            reject(new Error(result.error && result.error.message || "getFileAsync failed"));
            return;
          }
          var myFile = result.value;
          var sliceCount = myFile.sliceCount;
          var received = 0;
          var docdata = [];
          function _getSlice(i) {
            myFile.getSliceAsync(i, function (sr) {
              if (sr.status !== Office.AsyncResultStatus.Succeeded) {
                myFile.closeAsync();
                reject(new Error("Slice " + i + " failed"));
                return;
              }
              if (sr.value && sr.value.data) {
                var d = sr.value.data;
                docdata = docdata.concat(Array.isArray(d) ? d : Array.from(new Uint8Array(d)));
              }
              received++;
              if (received === sliceCount) {
                myFile.closeAsync();
                var blob = new Blob([new Uint8Array(docdata)], {
                  type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                });
                _writeBlob(blob, formData.filename).then(resolve).catch(reject);
              } else {
                _getSlice(received);
              }
            });
          }
          _getSlice(0);
        });
      } catch (e) { reject(e); }
    }).then(function () {
      showToast("✅ Saved: " + formData.filename, "ok");
      if (eli.activity && eli.activity.add) {
        eli.activity.add({
          type: "build-draft", icon: "💾", label: "Build Draft · Save",
          summary: "Saved " + formData.filename,
          payload: { filename: formData.filename, entity: formData.entity, type: formData.type },
        });
      }
      _recordStatSafe("draftsCreated");
      setTimeout(function () { _show({}); }, 800);
    }).catch(function (err) {
      eli.log.event("tool", "build_draft_save_failed", { msg: err && err.message });
      showToast("Save failed: " + (err && err.message), "err");
    });
  }

  // Browser-side blob write. Modern browsers get the system Save dialog
  // via showSaveFilePicker; older paths fall back to <a download>.
  function _writeBlob(blob, fileName) {
    if (window.showSaveFilePicker) {
      return window.showSaveFilePicker({
        suggestedName: fileName,
        types: [{
          description: "Word Document",
          accept: { "application/vnd.openxmlformats-officedocument.wordprocessingml.document": [".docx"] },
        }],
      }).then(function (handle) {
        return handle.createWritable().then(function (w) {
          return w.write(blob).then(function () { return w.close(); });
        });
      });
    }
    return new Promise(function (resolve) {
      var link = document.createElement("a");
      link.href = window.URL.createObjectURL(blob);
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      // Revoke after a tick so the browser actually fetches the blob.
      setTimeout(function () { window.URL.revokeObjectURL(link.href); }, 1000);
      resolve();
    });
  }

  // Declarative step→handler map. Adding a new step is one line:
  //   STEP_HANDLERS["foo"] = function (result, mount, opts, step) { ... };
  // Keep handlers small — extract to _render<Foo>Panel above if they grow.
  var STEP_HANDLERS = {
    logic: function () { _renderLogicPanel(); },
    templates: function () { _runStep2(); },
    error_review: function () { _runStep3ErrorReview(); },
    save: function () { _runStep4SaveSend(); },
  };

  function _show(opts) {
    opts = opts || {};
    var mount = document.getElementById("_eli3_dashboard_root");

    eli.events.safeAsync(_scanDocForOars(), "build_draft.oars_scan")
      .then(function (scan) {
        var input = {
          bodyText: (scan && scan.bodyText) || "",
          headerText: (scan && scan.headerText) || "",
          footerFile: _footerFile,
        };
        return eli.events.safeAsync(analyze(input, providers), "build_draft.analyze");
      })
      .then(function (result) {
        if (!result) return;
        if (result.hasOars && result.detectedType && !(result.persisted && result.persisted.type)) {
          eli.events.safeAsync(
            _persistAgreementState("OARS DATA", result.detectedType, { fields: result.fields }),
            "build_draft.persist"
          );
          showToast("🔍 Detected: " + result.detectedType, "ok");
          eli.events.safeAsync(_findTemplateByType(result.detectedType), "build_draft.template_lookup").then(function (tpl) {
            if (tpl && tpl.name && tpl.content) {
              // FROM v2 showAutoFillHub line 21224: auto-load the template
              // when an OARS type matches. Async; the hub keeps rendering
              // while load happens in the background.
              showToast("📄 Loading Template: " + tpl.name, "info");
              eli.events.safeAsync(_loadTemplateToWord(tpl.content), "build_draft.template_load")
                .then(function () { showToast("✅ Template Loaded: " + tpl.name, "ok"); })
                .catch(function (err) {
                  eli.log.event("tool", "build_draft_tpl_load_failed", { msg: err && err.message });
                  showToast("Template load failed: " + (err && err.message), "err");
                });
            } else if (tpl && tpl.name) {
              showToast("📄 Matching template: " + tpl.name, "info");
            }
          });
        }
        renderHub({
          result: result,
          mount: mount,
          onClose: _goHome,
          onRunAll: eli.events.guard(function () {
            // Run All = Step 1 → Step 2 → preSave → Step 3. Wizard flag
            // makes each finished step auto-advance via setTimeout. If no
            // logic defs, skip Step 1 and jump to Step 2.
            _wizardMode = true;
            showToast("🚀 Starting Wizard…", "info");
            if (result.logicDefs && result.logicDefs.count) {
              _renderLogicPanel();
            } else {
              _runStep2();
            }
          }, "build_draft.run_all"),
          onTemplates: eli.events.guard(function () {
            _renderTemplatesPanel();
          }, "build_draft.templates"),
          onStep: eli.events.guard(function (id, step) {
            var handler = STEP_HANDLERS[id];
            if (handler) { handler(result, mount, opts, step); return; }
            renderStepStub && renderStepStub({
              mount: mount,
              step: step,
              onBack: function () { _show(opts); },
            });
          }, "build_draft.step"),
          onClearOars: eli.events.guard(function () {
            eli.events.safeAsync(eli.ui.confirm({
              title: "Clear OARS data?",
              message: "Removes the OARS data from the footer AND from this document. The doc itself isn't modified.",
            }), "build_draft.clear-oars.confirm")
              .then(function (ok) {
                if (!ok) return null;
                // Single canonical clear: kernel.clearOars() handles
                // in-memory state + Office settings + oars:cleared bus
                // emit. Falls back to the tool-local clear if kernel API
                // isn't available (older kernels).
                if (eli.dashboard && typeof eli.dashboard.clearOars === "function") {
                  eli.dashboard.clearOars();
                  return true;
                }
                return eli.events.safeAsync(_clearAgreementState(), "build_draft.clear-oars")
                  .then(function () {
                    if (eli.bus) eli.bus.emit(BUS_OARS_CLEARED, {});
                    return true;
                  });
              })
              .then(function (cleared) {
                if (!cleared) return; // user cancelled
                _footerFile = null;
                try { eli.compat.lsRemove("_eli3_oars_loaded"); }
                catch (e) { eli.log.event("tool", "build_draft_lsremove_failed", { msg: e && e.message }); }
                showToast("🗑️ OARS data + file cleared.", "ok");
                _show(opts);
              })
              .catch(function (err) {
                eli.log.event("tool", "build_draft_clear_oars_failed", { msg: err && err.message });
                showToast("Clear failed: " + (err && err.message), "err");
              });
          }, "build_draft.clear-oars"),
        });
      })
      .catch(function (err) {
        eli.log.event("tool", "build_draft_show_failed", { msg: err && err.message });
        showToast("Build Draft load failed: " + (err && err.message), "err");
      });
  }

  // Bus: kernel boot hook fires "oars:detected" when active doc has OARS.
  if (eli.bus && eli.bus.on) {
    eli.bus.on(BUS_OARS_DETECTED, function (payload) {
      _show({ source: "oars", payload: payload || {} });
    });
  }

  // Stat helper: kernel's eli.stats.record writes to IDB only — no trophy
  // dependency — so this is safe whether or not trophy_gallery is installed.
  // Try/catch guards against any unexpected throw from the kernel module
  // (older kernels, IDB closed during shutdown, etc.) so a failed stat
  // never blocks the user-visible action.
  function _recordStatSafe(name) {
    try {
      if (eli.stats && typeof eli.stats.record === "function") {
        eli.stats.record(name);
      }
    } catch (e) {
      eli.log.event("tool", "build_draft_stat_failed", { stat: name, msg: e && e.message });
    }
  }

  eli.register({
    tile: { app_build_draft: function () {
      // FROM v2 renderAutoFillHubUI line 21255: stat tracking on hub open.
      _recordStatSafe("appOpenedDraft");
      _show({ source: "tile" });
    } },
  });

  eli.log.event("tool", "build_draft_initialized", {});
}

jsonTools.css:
/* build_draft tool styles. Injected as <style data-tool="build_draft">. */

._eli3_bd_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}
._eli3_bd_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_bd_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b;
  padding: 0 4px;
}
._eli3_bd_back:hover { color: #1565c0; }
._eli3_bd_title { flex: 1; font: 800 16px/1.2 'Georgia', serif; color: #0f172a; }
._eli3_bd_overview {
  font: 600 11px/1 'Inter', sans-serif; color: #64748b;
  background: #f1f5f9; padding: 4px 10px;
}

._eli3_bd_oars_banner {
  display: flex; align-items: center; gap: 12px;
  margin: 12px 14px 0;
  padding: 12px 14px;
  background: linear-gradient(180deg, #eff6ff 0%, #dbeafe 100%);
  border: 1px solid #93c5fd;
}
._eli3_bd_oars_icon { font-size: 26px; }
._eli3_bd_oars_main { flex: 1; min-width: 0; }
._eli3_bd_oars_label { font: 800 9px/1 'Inter', sans-serif; text-transform: uppercase; letter-spacing: 0.6px; color: #1e3a8a; }
._eli3_bd_oars_value { font: 700 13px/1.3 'Georgia', serif; color: #0f172a; margin-top: 2px; }
._eli3_bd_oars_source { font: 600 10px/1.3 'Inter', sans-serif; color: #1e40af; text-transform: uppercase; letter-spacing: 0.4px; margin-top: 2px; }
._eli3_bd_oars_meta { font: 500 11px/1.2 'Inter', sans-serif; color: #1e40af; margin-top: 2px; }
._eli3_bd_oars_clear {
  background: none; border: none; cursor: pointer;
  font: 700 14px/1 'Inter', sans-serif; color: #475569;
  padding: 4px 8px;
}
._eli3_bd_oars_clear:hover { color: #ef4444; }

._eli3_bd_actions {
  display: flex; gap: 8px;
  padding: 14px 14px 0;
}
._eli3_bd_run_all {
  flex: 2;
  padding: 12px 14px;
  font: 800 12px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  transition: transform .12s, box-shadow .12s;
}
._eli3_bd_run_all:hover { transform: translateY(-1px); box-shadow: 0 4px 12px rgba(21,101,192,0.30); }
._eli3_bd_run_all_icon { font-size: 16px; }
._eli3_bd_templates {
  flex: 1;
  padding: 12px 12px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a;
  border: 1px solid #b0bec5;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center; gap: 6px;
  text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_bd_templates:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); border-color: #90caf9; color: #1565c0; }
._eli3_bd_templates_icon { font-size: 14px; }

._eli3_bd_steps {
  flex: 1; overflow-y: auto;
  padding: 14px 14px 12px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_step {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  cursor: pointer;
  text-align: left;
  font: 600 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  transition: border-color .15s, background .15s;
}
._eli3_bd_step:hover { border-color: #1565c0; background: #f8fafc; }
._eli3_bd_step_n {
  flex: 0 0 24px;
  font: 800 13px/1 'Georgia', serif;
  color: #94a3b8;
  text-align: center;
}
._eli3_bd_step_icon { font-size: 18px; flex: 0 0 auto; }
._eli3_bd_step_info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
._eli3_bd_step_label { font: 700 12px/1.2 'Inter', sans-serif; color: #0f172a; }
._eli3_bd_step_desc { font: 400 11px/1.3 'Inter', sans-serif; color: #64748b; }
._eli3_bd_step_arrow { font-size: 14px; color: #94a3b8; flex: 0 0 auto; }
._eli3_bd_step_badge {
  display: inline-block;
  margin-left: 6px;
  padding: 2px 7px;
  font: 800 9px/1.2 'Inter', sans-serif;
  background: #fef3c7; color: #92400e;
  vertical-align: 1px;
}

/* Bracket Cleaner panel */
._eli3_bd_cleaner_intro {
  padding: 12px 14px;
  margin: 12px 14px 0;
  background: #fff7ed;
  border-left: 4px solid #f59e0b;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #5d4037;
}
._eli3_bd_cleaner_list {
  flex: 1; overflow-y: auto;
  padding: 12px 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_cleaner_empty {
  text-align: center; padding: 30px 0;
  font: 600 12px/1.4 'Inter', sans-serif; color: #94a3b8;
  font-style: italic;
}
._eli3_bd_cleaner_row {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #b0bec5;
}
._eli3_bd_cleaner_row:hover { border-left-color: #1565c0; }
._eli3_bd_cleaner_left { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; }
._eli3_bd_cleaner_right { display: flex; gap: 6px; flex: 0 0 auto; }
._eli3_bd_cleaner_tag {
  font: 800 10px/1 'Inter', sans-serif;
  color: #475569;
  background: #f1f5f9;
  padding: 3px 6px;
  flex: 0 0 auto;
}
._eli3_bd_cleaner_tag_money { background: #d1fae5; color: #065f46; }
._eli3_bd_cleaner_text {
  font: 600 12px/1.3 'JetBrains Mono', monospace;
  color: #0f172a;
  word-break: break-word;
}
._eli3_bd_action_btn {
  padding: 6px 10px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a; border: 1px solid #b0bec5;
  cursor: pointer;
  white-space: nowrap;
}
._eli3_bd_action_btn:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); border-color: #90caf9; color: #1565c0; }
._eli3_bd_action_help { color: #1565c0; }
._eli3_bd_cleaner_done { padding: 12px 14px; border-top: 1px solid #e2e8f0; }

/* SOW Helper modal */
._eli3_bd_sow_intro {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #475569;
  margin-bottom: 12px;
}
._eli3_bd_sow_options { display: flex; flex-direction: column; gap: 6px; }
._eli3_bd_sow_option {
  padding: 10px 12px;
  text-align: left;
  background: #fff;
  border: 1px solid #e2e8f0;
  cursor: pointer;
  display: flex; flex-direction: column; gap: 3px;
  transition: border-color .15s, background .15s;
}
._eli3_bd_sow_option:hover { border-color: #1565c0; background: #f8fafc; }
._eli3_bd_sow_option_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #1565c0;
  text-transform: uppercase; letter-spacing: 0.4px;
}
._eli3_bd_sow_option_desc {
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #334155;
}

/* Dark-mode for cleaner + SOW */
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_intro {
  background: rgba(245,158,11,0.10); color: #fde68a; border-left-color: #f59e0b;
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_row {
  background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.10); border-left-color: rgba(255,255,255,0.20);
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_text { color: #e2e8f0; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_tag { background: rgba(255,255,255,0.08); color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_tag_money { background: rgba(16,185,129,0.18); color: #6ee7b7; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_cleaner_done { border-top-color: rgba(255,255,255,0.10); }
body.beta-ui-active:not(.light-mode) ._eli3_bd_sow_option {
  background: rgba(255,255,255,0.04); border-color: rgba(255,255,255,0.10);
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_sow_option:hover { border-color: #f2d866; background: rgba(255,255,255,0.06); }
body.beta-ui-active:not(.light-mode) ._eli3_bd_sow_option_label { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_sow_option_desc { color: #cbd5e1; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_sow_intro { color: #94a3b8; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_badge { background: rgba(245,158,11,0.18); color: #fbbf24; }

._eli3_bd_foot {
  flex: 0 0 auto;
  padding: 8px 14px 12px;
  font: 400 10px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  text-align: center;
  border-top: 1px dashed #e2e8f0;
}

._eli3_bd_step_body { flex: 1; overflow-y: auto; padding: 24px 16px; }
._eli3_bd_step_pending { text-align: center; padding: 30px 12px; }
._eli3_bd_step_pending_icon { font-size: 42px; margin-bottom: 10px; }
._eli3_bd_step_pending_title { font: 800 16px/1.2 'Georgia', serif; color: #0f172a; margin-bottom: 6px; }
._eli3_bd_step_pending_desc { font: 400 12px/1.5 'Inter', sans-serif; color: #64748b; max-width: 360px; margin: 0 auto; }

/* Dark mode */
body.beta-ui-active:not(.light-mode) ._eli3_bd_root {
  background: linear-gradient(160deg, #0f172a 0%, #1e293b 100%);
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_bar { border-bottom-color: rgba(255,255,255,0.10); }
body.beta-ui-active:not(.light-mode) ._eli3_bd_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_back { color: #cbd5e1; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_back:hover { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_overview { background: rgba(255,255,255,0.08); color: #cbd5e1; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_oars_banner {
  background: linear-gradient(180deg, rgba(59,130,246,0.18), rgba(59,130,246,0.08));
  border-color: rgba(147,197,253,0.35);
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_oars_label { color: #93c5fd; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_oars_value { color: #e2e8f0; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_oars_meta { color: #93c5fd; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step {
  background: rgba(255,255,255,0.03); border-color: rgba(255,255,255,0.10);
}
body.beta-ui-active:not(.light-mode) ._eli3_bd_step:hover { border-color: #f2d866; background: rgba(255,255,255,0.05); }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_label { color: #e2e8f0; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_desc { color: #94a3b8; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_n { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_arrow { color: #cbd5e1; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_foot { color: #64748b; border-top-color: rgba(255,255,255,0.10); }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_pending_title { color: #f2d866; }
body.beta-ui-active:not(.light-mode) ._eli3_bd_step_pending_desc { color: #94a3b8; }

@media (max-width: 380px) {
  ._eli3_bd_run_all { font-size: 11px; padding: 10px 8px; }
  ._eli3_bd_templates { font-size: 10px; padding: 10px 8px; }
}

/* =====================================================================
   Step 1 — Logic Builder form
   ===================================================================== */
._eli3_bd_logic ._eli3_bd_bar { background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%); }
._eli3_bd_logic_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px 14px 4px;
  display: flex; flex-direction: column; gap: 14px;
}
._eli3_bd_logic_group {
  background: #fff;
  border: 1px solid #e2e8f0;
  padding: 12px 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_bd_logic_label {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #0f172a;
}
._eli3_bd_logic_warning {
  font: 500 10px/1.2 'Inter', sans-serif;
  color: #b45309; background: #fef3c7;
  padding: 3px 8px;
  text-transform: none; letter-spacing: 0;
}
._eli3_bd_logic_hint {
  font: 400 10px/1.3 'Inter', sans-serif;
  color: #64748b; font-style: italic;
}
._eli3_bd_logic_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._eli3_bd_logic_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21,101,192,0.18);
}
._eli3_bd_logic_actions {
  flex: 0 0 auto;
  display: flex; gap: 8px;
  padding: 12px 14px;
  border-top: 1px solid #e2e8f0;
  background: #f8fafc;
}
._eli3_bd_logic_empty {
  flex: 1 1 auto;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 40px 24px;
  text-align: center;
  gap: 12px;
}
._eli3_bd_logic_empty_icon { font-size: 48px; opacity: 0.6; }
._eli3_bd_logic_empty_title { font: 800 14px/1.2 'Inter', sans-serif; color: #0f172a; letter-spacing: 0.4px; }
._eli3_bd_logic_empty_desc { font: 500 12px/1.5 'Inter', sans-serif; color: #64748b; max-width: 320px; }
._eli3_bd_logic_empty_desc code {
  font: 600 11px/1 monospace;
  background: #f1f5f9; padding: 2px 5px;
  color: #1565c0;
}
._eli3_bd_logic_oars_btn { margin-top: 12px; min-width: 200px; }

/* =====================================================================
   Step 2 — Template Fill form
   ===================================================================== */
._eli3_bd_fill ._eli3_bd_bar { background: linear-gradient(180deg, #f8fafc 0%, #ecfdf5 100%); }
._eli3_bd_fill_loaded {
  display: flex; align-items: center; gap: 10px;
  margin: 12px 14px;
  padding: 10px 12px;
  background: linear-gradient(180deg, #ecfdf5 0%, #d1fae5 100%);
  border: 1px solid #6ee7b7;
}
._eli3_bd_fill_loaded_main { flex: 1; min-width: 0; }
._eli3_bd_fill_loaded_label {
  font: 800 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #047857;
}
._eli3_bd_fill_loaded_name {
  font: 700 12px/1.3 'Georgia', serif;
  color: #064e3b; margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
._eli3_bd_fill_autofill_btn {
  flex: 0 0 auto;
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #fff;
  border: 1.5px solid #b45309;
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 9px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(245,158,11,0.25);
}
._eli3_bd_fill_autofill_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #fbbf24, #f59e0b);
  box-shadow: 0 4px 12px rgba(245,158,11,0.35);
}
._eli3_bd_fill_autofill_btn:disabled { opacity: 0.6; cursor: not-allowed; }
._eli3_bd_fill_status {
  flex: 1 0 100%;
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #047857; margin-top: 6px;
}
._eli3_bd_fill_drop {
  margin: 12px 14px;
  padding: 24px 16px;
  border: 2px dashed #cbd5e1;
  background: #f8fafc;
  text-align: center;
  cursor: pointer;
  transition: all 0.15s;
